@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosOffsetsParser
import com.bedalton.creatures.caos.antlr.CaosOffsetsParserBaseListener
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.Token
import com.bedalton.creatures.caos.server.PositionImpl
import com.bedalton.creatures.caos.utils.token
import kotlin.math.max

/**
 * Finds block ranges for scripts in file
 */
internal class CaosOffsetsWalker : CaosOffsetsParserBaseListener() {
    private val mOffsets: MutableList<com.bedalton.creatures.caos.collectors.BlockRange> = mutableListOf()
    val offsets: Array<com.bedalton.creatures.caos.collectors.BlockRange> get() = mOffsets.toTypedArray()
    private var start: Token? = null
    private var startCommand: String? = null
    private var isDDe: Boolean = false
    private val dde = token("dde:")
    private var depth = 0

    override fun enterEveryRule(ctx: ParserRuleContext) {
        super.enterEveryRule(ctx)
        if (start == null) {
            startCommand = null
            start = ctx.start
        }
    }

    override fun enterScriptStart(ctx: CaosOffsetsParser.ScriptStartContext) {
        super.enterScriptStart(ctx)
        if (isDDe) {
            isDDe = false
            return
        }

        val start = start
        val newStart = ctx.start!!
        if (start != null && start.startIndex != ctx.start!!.startIndex) {
            mOffsets.add(
                com.bedalton.creatures.caos.collectors.BlockRange(
                    startToken = startCommand,
                    endToken = null,
                    startIndex = start.startIndex,
                    endIndex = max(start.stopIndex, newStart.startIndex - 1),
                    start = PositionImpl(
                        line = start.line - 1,
                        character = start.charPositionInLine
                    ),
                    end = PositionImpl(
                        line = newStart.line - 1,
                        character = newStart.charPositionInLine
                    ),
                    null,
                    depth = 0
                )
            )
        }
        depth++
        this.start = newStart
        this.startCommand = ctx.text
    }

    override fun enterControlStatement(ctx: CaosOffsetsParser.ControlStatementContext) {
        super.enterControlStatement(ctx)
        depth++
    }

    override fun exitControlStatement(ctx: CaosOffsetsParser.ControlStatementContext) {
        super.exitControlStatement(ctx)
        depth--
    }

    override fun enterScriptEnd(ctx: CaosOffsetsParser.ScriptEndContext) {
        super.enterScriptEnd(ctx)
        val start = start
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startCommand,
                ctx.text,
                start,
                ctx.stop!!,
                null,
                depth = 0
            )
        )
        startCommand = null
        this.start = null
        depth--
    }

    override fun exitEnumStatement(ctx: CaosOffsetsParser.EnumStatementContext) {
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = ctx.getChild(0)?.text ?: "enum",
                endToken = "next",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun exitEscnStatement(ctx: CaosOffsetsParser.EscnStatementContext) {
        super.exitEscnStatement(ctx)
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = "escn",
                endToken = "nscn",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun exitLoopStatement(ctx: CaosOffsetsParser.LoopStatementContext) {
        super.exitLoopStatement(ctx)
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = "loop",
                endToken = if (ctx.EVER() != null) "ever" else "untl",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun exitRepsStatement(ctx: CaosOffsetsParser.RepsStatementContext) {
        super.exitRepsStatement(ctx)
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = "reps",
                endToken = "repe",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun exitSubrStatement(ctx: CaosOffsetsParser.SubrStatementContext) {
        super.exitSubrStatement(ctx)
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = "subr",
                endToken = "retn",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun exitDoifStatement(ctx: CaosOffsetsParser.DoifStatementContext) {
        super.exitDoifStatement(ctx)
        val start = ctx.start
            ?: return
        val end = ctx.stop
            ?: return
        mOffsets.add(
            com.bedalton.creatures.caos.collectors.BlockRange(
                startToken = "doif",
                endToken = "endi",
                start = start,
                end = end,
                null,
                depth = depth
            )
        )
    }

    override fun enterEof(ctx: CaosOffsetsParser.EofContext) {
        super.enterEof(ctx)
        val start = start
        val end = ctx.start!!
        if (start != null) {
            mOffsets.add(
                com.bedalton.creatures.caos.collectors.BlockRange(
                    startToken = startCommand,
                    endToken = null,
                    start = start,
                    end = end,
                    null,
                    depth = 0
                )
            )
        }
    }

}