package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.Caos2PrayParser
import com.bedalton.creatures.caos.antlr.Caos2PrayParserBaseListener
import com.bedalton.creatures.caos.server.RangeWithIndexImpl
import com.bedalton.creatures.caos.utils.stripSurroundingQuotes
import org.antlr.v4.kotlinruntime.ParserRuleContext

/**
 * Walks a script only pulling out the CAOS2Pray comments
 */
class Caos2PrayWalker : Caos2PrayParserBaseListener() {

    private val mCaos2Comments: MutableList<ParserItem.Caos2Comment> = mutableListOf()
    val caos2Comments get() = mCaos2Comments

    override fun enterCaos2Tag(ctx: Caos2PrayParser.Caos2TagContext) {
        super.enterCaos2Tag(ctx)

        val start = ctx.CAOS2_START()?.symbol
            ?: return
        val wordContext = ctx.findCaos2TagName()
            ?: return
        val eq = ctx.CAOS2_EQUALS()?.symbol
            ?: return
        val token = ParserItem.TokenVal(
            wordContext.textRangeWithoutParserIndex(),
            wordContext.text.stripSurroundingQuotes()
        )
        mCaos2Comments.add(
            ParserItem.Caos2Comment(
                textRange = ctx.textRangeWithoutParserIndex(),
                text = ctx.text.trim(),
                token = token,
                values = caos2Values(ctx),
                eq = ParserItem.TokenVal(
                    textRange = eq.textRangeWithoutParserIndex(),
                    value = "="
                ),
                caos2Hash = ParserItem.TokenVal(
                    textRange = start.textRangeWithoutParserIndex(),
                    value = "*#"
                ),
            )
        )
    }

    override fun enterCaos2Comand(ctx: Caos2PrayParser.Caos2ComandContext) {
        super.enterCaos2Comand(ctx)

        val start = ctx.CAOS2_START()?.symbol
            ?: return
        val wordContext = ctx.findCaos2Word()
            ?: return
        val token = ParserItem.TokenVal(
            RangeWithIndexImpl(wordContext.start!!, wordContext.stop!!, -1),
            wordContext.text.stripSurroundingQuotes()
        )
        mCaos2Comments.add(
            ParserItem.Caos2Comment(
                textRange = ctx.textRangeWithoutParserIndex(),
                text = ctx.text.trim(),
                token = token,
                values = caos2Values(ctx),
                eq = null,
                caos2Hash = ParserItem.TokenVal(
                    textRange = start.textRangeWithoutParserIndex(),
                    value = "*#"
                ),
            )
        )
    }

    private fun caos2Values(ctx: ParserRuleContext): Array<ParserItem<*>> {
        val intRegex = "[-+]?\\d+".toRegex()
        return ctx.children
            .orEmpty()
            .filterIsInstance<Caos2PrayParser.Caos2ValueContext>()
            .map {
                val text = it.text
                val range = it.textRangeWithoutParserIndex()
                if (intRegex.matches(text)) {
                    ParserItem.IntVal(
                        range,
                        text.toInt()
                    )
                } else if (text.startsWith('"') && text.endsWith('"')) {
                    ParserItem.C2eStringVal(
                        range,
                        text.stripSurroundingQuotes()
                    )
                } else {
                    ParserItem.TokenVal(
                        range,
                        text.stripSurroundingQuotes()
                    )
                }
            }
            .toTypedArray()
    }


}