@Suppress("ConstPropertyName")
internal object InlayKind {
    /**
     * An inlay hint that for a type annotation.
     */
    const val Type = 1
    /**
     * An inlay hint that is for a parameter.
     */
    const val Parameter = 2
}

interface CaosScriptHintsProvider<T> {
    fun isApplicable(variant: GameVariant, element: T): Boolean
    fun provideHints(variant: GameVariant, element: T): List<InlayHint>
    val description: String
    val option: String
    val priority: Int
}

@JsExport
fun getInlayOptions(): Array<String> {
    return (CommandInlayHintsProvider.options + ArgumentInlayHintsProvider.options + EqualityInlayHintsProvider.options)
}

@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
fun getInlayHints(
    parseResult: ParseResult,
    disabled: Array<String>,
    folds: Array<Range>,
    minimumParameterCount: Int? = null
): Array<InlayHint> {
    val variant =  GameVariant.fromVal(parseResult.variant)
    val commandCalls = parseResult.commandCalls
    val commandHints = commandCalls
        .flatMap { commandCall ->
            val commandHints = if (commandCall.command.parameters.size > (minimumParameterCount ?: 2)) {
                CommandInlayHintsProvider.resolve(
                    variant,
                    disabled,
                    folds,
                    commandCall
                )?.provideHints(variant, commandCall)
                    .orEmpty()
            } else {
                emptyList()
            }

            commandHints + commandCall.arguments.flatMap { argument ->
                val element = Pair(commandCall, argument)
                ArgumentInlayHintsProvider.resolve(
                    variant,
                    disabled,
                    folds,
                    element
                )?.provideHints(variant, element).orEmpty()
            }
        }
    val equalityStatementHints = parseResult.equalityStatements
        .flatMap {
            EqualityInlayHintsProvider.resolve(
                variant,
                disabled,
                folds,
                it
            )?.provideHints(variant, it).orEmpty()
        }
    return (commandHints + equalityStatementHints).distinctBy { it.code() }.toTypedArray()
}

internal val EMPTY_INLAY_LIST: List<InlayHint> = emptyList()

interface CommandInlayHintsProvider : CaosScriptHintsProvider<CommandCall> {

    companion object {

        private const val PREFIX = "inlayHints."

        // When resolving hint providers, ensure element is not folded first
        fun resolve(
            variant: GameVariant,
            disabled: Array<String>,
            folds: Array<Range>,
            element: CommandCall,
        ): CommandInlayHintsProvider? {
            return if (!inRange(element.textRange, folds)) {
                values.firstOrNull {
                    (PREFIX + it.option) !in disabled && it.isApplicable(variant, element)
                }
            } else {
                null
            }
        }

        val values: List<CommandInlayHintsProvider> by lazy {
            ParameterHintsProvider.values()
                .sortedByDescending { it.priority }
        }

        val options: Array<String>
            get() = values.map {
                (PREFIX + it.option)
            }.toTypedArray()
    }
}

interface ArgumentInlayHintsProvider : CaosScriptHintsProvider<Pair<CommandCall, Argument>> {

    companion object {

        private const val PREFIX = "inlayHints."

        // When resolving hint providers, ensure element is not folded first
        fun resolve(
            variant: GameVariant,
            disabled: Array<String>,
            folds: Array<Range>,
            element: Pair<CommandCall, Argument>,
        ): ArgumentInlayHintsProvider? {
            return if (!inRange(element.second.textRange, folds)) {
                values.firstOrNull {
                    (PREFIX + it.option) !in disabled && it.isApplicable(variant, element)
                }
            } else {
                null
            }
        }

        val values: List<ArgumentInlayHintsProvider> by lazy {
            ArgumentInlayTypeHint.values()
                .sortedByDescending { it.priority }
        }

        val options: Array<String>
            get() = values.map {
                (PREFIX + it.option)
            }.toTypedArray()
    }
}

interface EqualityInlayHintsProvider : CaosScriptHintsProvider<EqualityStatement> {

    companion object {

        private const val PREFIX = "inlayHints.equality."

        // When resolving hint providers, ensure element is not folded first
        fun resolve(
            variant: GameVariant,
            disabled: Array<String>,
            folds: Array<Range>,
            element: EqualityStatement,
        ): EqualityInlayHintsProvider? {
            return if (!inRange(element.textRange, folds))
                values.firstOrNull { (PREFIX + it.option) !in disabled && it.isApplicable(variant, element) }
            else
                null
        }

        private val values: List<EqualityInlayHintsProvider> by lazy {
            EqualityInlayHints.values()
                .sortedByDescending { it.priority }
        }

        val options: Array<String>
            get() = values.map {
                (PREFIX + it.option)
            }.toTypedArray()
    }
}

data class InlayHintImpl(
    override val position: Position,
    override val label: String,
    override val kind: Int? = InlayKind.Type,
    override val textEdits: Array<TextEdit>? = null,
    override val tooltip: String? = null,
    override val paddingLeft: Boolean? = null,
    override val paddingRight: Boolean? = null,
//    override val data: Any? = null,

    ) : InlayHint {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is InlayHintImpl) return false

        if (position != other.position) return false
        if (label != other.label) return false
        if (kind != other.kind) return false
        if (textEdits != null) {
            if (other.textEdits == null) return false
            if (!textEdits.contentEquals(other.textEdits)) return false
        } else if (other.textEdits != null) return false
        if (tooltip != other.tooltip) return false
        if (paddingLeft != other.paddingLeft) return false
        if (paddingRight != other.paddingRight) return false
//        if (data != other.data) return false

        return true
    }

    override fun hashCode(): Int {
        var result = position.hashCode()
        result = 31 * result + label.hashCode()
        result = 31 * result + (kind ?: 0)
        result = 31 * result + (textEdits?.contentHashCode() ?: 0)
        result = 31 * result + (tooltip?.hashCode() ?: 0)
        result = 31 * result + (paddingLeft?.hashCode() ?: 0)
        result = 31 * result + (paddingRight?.hashCode() ?: 0)
//        result = 31 * result + data.hashCode()
        return result
    }
}

fun InlayHint.code(): String {
    return "${position.line}:${position.character}:${label}"
}