/**
 * Interface marking a class as having a get operator
 */
internal interface CommandGetter {
    operator fun get(tokens: IntArray, bias: ValueType = ValueType.ANY): Pair<CaosCommand, Int>?
}

/**
 * Makes a list of CaosCommands queryable by token
 */
private class CaosCommandMap(commands: Map<Int, CaosCommand>, tokenIds: Map<String, IntArray>) : CommandGetter {
    private val map = mapCommands(commands, tokenIds)

    /**
     * Returns a match with maximum range of work token ints
     */
    override operator fun get(tokens:IntArray, bias: ValueType): Pair<CaosCommand, Int>? {
        val numTokens = tokens.size
        if (numTokens < 1)
            return null
        var matchSets = map.filter { tokens[0] == it.first[0] }
        var depth = 0
        for (i in tokens.indices) {
            val tempMatches = matchSets.filter { it.first.size > i && tokens[i] == it.first[i] }
            if (tempMatches.isNotEmpty()) {
                depth++
                matchSets = tempMatches
            }
        }
        //val searchTokens = tokens.joinToString{ token(it) }
        matchSets = matchSets.filter {
            //Log.i("CaosCommandMap", "Depth: $depth; TokenSize: ${it.first.size}; Tokens: [$searchTokens]; Command: [${it.first.joinToString { token(it) }}]")
            it.first.size == depth
        }
        if (matchSets.isEmpty()) {
            //Log.e("CaosCommandMap", "Failed to find command matching: [${tokens.joinToString()}].")
            return null
        }
        if (matchSets.size > 1) {
            throw Exception("Too many results returned for command ${tokens.copyOfRange(0, depth).joinToString(" ") {
                token(
                    it
                ).uppercase()
            }}")
        }
        var matches = matchSets.flatMap { it.second.toList() }
        matches = matches.filter { it.returnType == bias || it.returnType like bias }.nullIfEmpty() ?: matches
        return Pair(matches.first(), depth)
    }
}


/**
 * @param commands == Commands by ID
 * @param tokenIds == Command Ids by token int array
 */
private fun mapCommands(
    commands: Map<Int, CaosCommand>,
    tokenIds: Map<String, IntArray>
): List<Pair<IntArray, Array<CaosCommand>>> {
    return tokenIds.map map@{ (commandString, commandIds) ->
        val tokens = commandString.split(' ').map {
            token(it)
        }.toIntArray()
        val matchingCommands = commands.filter { it.key in commandIds }.values.toTypedArray()
        if (matchingCommands.size != commandIds.size)
            throw Exception("Mismatched token to id conversion. Failed to find all referenced commands for '$commandString'")
        tokens to matchingCommands
    }
}

/**
 * A queryable CAOS lib object
 */
@Suppress("unused")
internal class CaosLib internal constructor(private val lib: CaosLibDefinitions, val variant: CaosVariantData) {

    private val commandsById = lib.commands.map {
        it.key.toInt() to it.value
    }.toMap()

    /**
     * Rvalue definitions getter
     */
    val rvalue: CommandGetter = CaosCommandMap(commandsById, variant.rvalues.map { (commandString, commandIds) ->
        commandString to commandIds.values.toIntArray()
    }.toMap())

    /**
     * List of all RValues in this variant
     */
    val rvalues: Array<CaosCommand> by lazy {
        val rvalueCommandIds = variant.rvalues.values.flatMap { returnTypeIdMap ->
            returnTypeIdMap.values
        }
        lib.commands.values.filter { command ->
            command.id in rvalueCommandIds
        }.toTypedArray()
    }

    /**
     * LValue definitions getter
     */
    val lvalue: CommandGetter = CaosCommandMap(commandsById, variant.lvalues.map {(commandString, commandId) ->
        commandString to intArrayOf(commandId)
    }.toMap())


    /**
     * List of all LValues in this variant
     */
    val lvalues: Array<CaosCommand> by lazy {
        val lvalueCommandIds = variant.lvalues.values
        lib.commands.values.filter { command ->
            command.id in lvalueCommandIds
        }.toTypedArray()
    }

    /**
     * Command definitions getter
     */
    val command: CommandGetter = CaosCommandMap(commandsById, variant.commands.map {(commandString, commandId) ->
        commandString to intArrayOf(commandId)
    }.toMap())

    /**
     * List of all commands in this variant
     */
    val commands: Array<CaosCommand> by lazy {
        val commandIds = variant.commands.values
        lib.commands.values.filter { command ->
            command.id in commandIds
        }.toTypedArray()
    }

    val allCommands: Array<CaosCommand> by lazy {
        val commandIds = variant.rvalues.values.flatMap { it.values } + variant.lvalues.values + variant.commands.values
        lib.commands.values.filter { command ->
            command.id in commandIds
        }.toTypedArray()
    }

    /**
     * Values lists getter
     */
    val valuesLists: Array<CaosValuesList>
        get() = CaosLibs.getValuesLists(variant.valuesListsIds)

    @JsName("valuesListWithId")
    fun valuesList(valuesListId: Int): CaosValuesList? = CaosLibs.valuesList[valuesListId]

    @JsName("valuesListWithName")
    fun valuesList(valuesListName: String): CaosValuesList? = valuesLists.firstOrNull { it.name like valuesListName }

    /**
     * Getter for variable max value type
     */
    val variableTypeMaxValues: HasGetter<CaosScriptVarTokenGroup, Int?> = variant.vars


    // Variant query information
    /** Variant CODE */
    val variantCode: String = variant.code

    /** The full name of this variant */
    val variantName: String = variant.name

    /** Helper command to check variant oldness (ie. C1,C2) */
    val isOldVariant: Boolean
        get() = variant.isOld

    /** Helper command to check variant newness (ie. CV,C3,DS) */
    val isNewVariant: Boolean
        get() = variant.isNew

    internal operator fun get(type: CommandType): CommandGetter {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }
    }

    @JsName("getCommandWithTypeEnum")
    internal operator fun get(type: CommandType, tokens: IntArray, bias: ValueType = ValueType.ANY): Pair<CaosCommand, Int>? {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, bias]
    }

    @JsName("getCommandFromString")
    internal operator fun get(type: CommandType, commandString: String, bias: ValueType = ValueType.ANY): Pair<CaosCommand, Int>? {
        val tokens = commandString.split("\\s+")
            .map { token(commandString.lowercase()) }
            .toIntArray()
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, bias]
    }

    @JsName("get")
    internal operator fun get(type: CommandType, tokens: IntArray, bias: Int = ValueType.ANY.value): Pair<CaosCommand, Int>? {
        return when (type) {
            CommandType.RVALUE -> rvalue
            CommandType.LVALUE -> lvalue
            CommandType.COMMAND -> command
        }[tokens, ValueType.fromIntValue(bias)]
    }
}

@JsExport
@JsName("getValuesList")
fun getValuesList(id:Int) : CaosValuesList? {
    return universalLib.valuesLists["list_$id"]
}

@JsExport
@JsName("getValueTypeName")
fun getValueTypeName(value:Int) : String? {
    return ValueType.simpleName(value)
}

/**
 * Holder object to fetch and store the variant Libs
 */
internal object CaosLibs {
    private val libs = mutableMapOf<String, CaosLib>()

    val valuesList: HasGetter<Int, CaosValuesList?> = object : HasGetter<Int, CaosValuesList?> {
        override operator fun get(key: Int) = universalLib.valuesLists["list_$key"]
    }

    fun getValuesLists(ids: Array<Int>): Array<CaosValuesList> {
        return universalLib.valuesLists.values.filter { list ->
            list.id in ids
        }.toTypedArray()
    }

    val valuesLists: HasGetter<CaosVariant, List<CaosValuesList>> by lazy {
        HasGetterImpl { variant ->
            universalLib.variantMap[variant.code]?.valuesLists.orEmpty()
        }
    }

    fun commands(tokens:IntArray): Pair<List<CaosCommand>, Int>? {
        val numTokens = tokens.size
        if (numTokens < 1)
            return null

        // Find first set of matches
        var matchSets = universalLib.commands.values.filter { command ->
            command.tokens[0] == tokens[0]
        }.nullIfEmpty()
            ?: return null

        var depth = 1
        if (matchSets.isNotEmpty() && tokens.size > 1) {
            var tempMatches = matchSets.filter { tokens[1] == it.tokens.getOrNull(1) }
            if (tempMatches.isNotEmpty()) {
                depth++
                matchSets = tempMatches
                if (tokens.size > 2) {
                    tempMatches = matchSets.filter { tokens[2] == it.tokens.getOrNull(2)}
                    if (tempMatches.isNotEmpty()) {
                        depth++
                        matchSets = tempMatches
                    }
                }
            }
        }
        //Log.i("CaosLib", "Matching set: [${matchSets.joinToString(",") { it.command }}]")
        matchSets = matchSets.filter { it.tokens.size == depth }
        //Log.i("CaosLib", "Matching set after token sizing for depth($depth): [${matchSets.joinToString(",") { it.command }}]")
        return Pair(matchSets, depth)
    }

    operator fun get(commandType: CommandType): Array<CaosCommand> {
        val filter: (CaosCommand) -> Boolean = when (commandType) {
            CommandType.LVALUE -> { command -> command.lvalue }
            CommandType.RVALUE -> { command -> command.rvalue }
            CommandType.COMMAND -> { command -> command.isCommand }
        }
        return universalLib.commands.values.filter(filter).toTypedArray()
    }

    operator fun get(variant: CaosVariant): CaosLib = get(variant.code)

    operator fun get(variantCode: String): CaosLib {
        libs[variantCode]?.let {
            return it
        }
        val variant = universalLib.variantMap[variantCode]
            ?: throw Exception("Invalid variant: '$variantCode' encountered. Known variants are: ${universalLib.variantMap.keys}")
        val lib = CaosLib(universalLib, variant)
        libs[variantCode] = lib
        return lib
    }
}


private fun normalize(commandString: String?): String? {
    return commandString
        ?.uppercase()
        ?.replace("\\s\\s+".toRegex(), " ")
}

enum class EqOp(val commonName: String, vararg val values: String) {
    EQUAL("Equals", "EQ", "="),
    NOT_EQUAL("Not Equal", "NE", "!=", "<>"),
    GREATER_THAN("Greater Than", "GT", ">"),
    LESS_THAN("Less Than", "LT", "<"),
    GREATER_THAN_EQUAL("Greater Than / Equal", "GE", ">="),
    LESS_THAN_EQUAL("Less Than / Equal", "LE", "<="),
    BITWISE_AND("Bitwise And", "BT"),
    BITWISE_NAND("Bitwise Nand", "BF"),
    INVALID("INVALID", "??");

    companion object {
        fun fromValue(value: String): EqOp {
            return when (value.uppercase()) {
                "EQ", "=" -> EQUAL
                "NE", "!=", "<>" -> NOT_EQUAL
                "GT", ">" -> GREATER_THAN
                "GE", ">=" -> GREATER_THAN_EQUAL
                "LT", "<" -> LESS_THAN
                "LE", "<=" -> LESS_THAN_EQUAL
                "BT" -> BITWISE_AND
                "BF" -> BITWISE_NAND
                else -> INVALID
            }
        }
    }
}

internal fun Pair<List<CaosCommand>, Int>?.filterByType(commandType:CommandType):Pair<List<CaosCommand>, Int>? {
    if (this == null)
        return null
    val filter: (CaosCommand) -> Boolean = when (commandType) {
        CommandType.LVALUE -> { command -> command.lvalue }
        CommandType.RVALUE -> { command -> command.rvalue }
        CommandType.COMMAND -> { command -> command.isCommand }
    }
    val filtered = first.filter(filter)
    return Pair(filtered, second)
}

