@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosUniversalParser
import com.bedalton.creatures.caos.antlr.CaosUniversalParserBaseListener
import org.antlr.v4.kotlinruntime.ParserRuleContext
import org.antlr.v4.kotlinruntime.Token
import com.bedalton.creatures.caos.server.PositionImpl
import com.bedalton.creatures.caos.utils.insertFront
import com.bedalton.creatures.caos.utils.token
import kotlin.math.max

/**
 * Collects all control statement offsets
 * Control statements being ENUM..NEXT, REPS..REPE, etc..
 */
class ControlStatementOffsetsWalker(variant: String) : CaosUniversalParserBaseListener() {
    private val stack: MutableList<Pair<Int, ParserRuleContext>> = mutableListOf()
    private val mScriptOffsets: MutableList<BlockRange> = mutableListOf()
    val statementOffsets: List<BlockRange> get() = mScriptOffsets
    private var depth = 0
    private var skipNextNext: Boolean = false
    private val isNewVariant: Boolean = variant.uppercase() !in listOf("C1", "C2")
    private var isDDe: Boolean = false
    private val dde: Int = token("dde:")

    override fun enterWord(ctx: CaosUniversalParser.WordContext) {
        super.enterWord(ctx)
        skipNextNext = isNewVariant && token(ctx.text) in hasNextNext
        isDDe = !isNewVariant && token(ctx.text) == dde
    }

    /**
     * Control statement starts are DOIF,ENUM,REPS,LOOP, etc
     */
    override fun enterControlStatementStart(ctx: CaosUniversalParser.ControlStatementStartContext) {
        super.enterControlStatementStart(ctx)
        isDDe = false
        if (skipNextNext) {
            skipNextNext = false
        }
        stack.insertFront(Pair(token(ctx.text), ctx))
        depth++
    }

    /**
     * Control statement ends are ENDI,NEXT,REPE,UNTL, etc
     */
    override fun exitControlStatementEnd(ctx: CaosUniversalParser.ControlStatementEndContext) {
        super.exitControlStatementEnd(ctx)
        isDDe = false
        if (skipNextNext) {
            skipNextNext = false
            if (token(ctx.text) == NEXT) {
                return
            }
        }
        val start = when (token(ctx.text)) {
            ENDI -> DOIF
            EVER, UNTL -> LOOP
            RETN -> if (stack.size <= 1) SUBR else null
            NEXT -> ENUM
            REPE -> REPS
            NSCN -> ESCN
            else -> null
        } ?: return
        popUntil(start, ctx)
    }

    /**
     * Script starts are SCRP,ISCR,RSCR
     */
    override fun enterScriptStart(ctx: CaosUniversalParser.ScriptStartContext) {
        super.enterScriptStart(ctx)
        if (isDDe) {
            isDDe = false
            if (ctx.SCRP() != null)
                return
        }
        isDDe = false
        popAll(ctx)
        depth++
    }

    /**
     * Script end is ENDM
     */
    override fun enterScriptEnd(ctx: CaosUniversalParser.ScriptEndContext) {
        super.enterScriptEnd(ctx)
        popAll(ctx)
    }

    override fun enterEof(ctx: CaosUniversalParser.EofContext) {
        super.enterEof(ctx)
        popAll(ctx)
    }

    private fun popAll(ctx: ParserRuleContext) {
        depth = 0
        while (true) {
            val item = stack.removeFirstOrNull()
                ?: return
            popMismatch(item.second.text, item.second.start!!, ctx.start!!)
        }
    }

    private fun popUntil(startToken: IntArray, endCtx: ParserRuleContext) {
        var didFindStart = false
        while (true) {
            val item = stack.removeFirstOrNull()
                ?: break
            depth--
            if (depth < 0)
                depth = 0
            if (item.first !in startToken) {
                popMismatch(item.second.text, item.second.start!!, endCtx.start!!)
            } else {
                didFindStart = true
                popMatch(item.second.text, endCtx.text.lowercase(), item.second.start!!, endCtx.stop!!)
                break
            }
        }
        if (!didFindStart) {
            val start = endCtx.start
                ?: return
            val stop = endCtx.stop
                ?: return
            mScriptOffsets.add(
                BlockRange(
                    startToken = null,
                    endToken = endCtx.text,
                    startIndex = start.startIndex,
                    endIndex = stop.stopIndex,
                    start = PositionImpl(
                        line = start.line - 1,
                        character = start.charPositionInLine
                    ),
                    end = PositionImpl(
                        line = stop.line - 1,
                        character = stop.charPositionInLine,//max(0, start.charPositionInLine - 1),
                    ),
                    null,
                    depth = depth
                )
            )
        }
    }


    private fun popMatch(startCommand: String, endToken: String, start: Token, end: Token) {
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand.lowercase(),
                endToken = endToken.lowercase(),
                startIndex = start.startIndex,
                endIndex = end.stopIndex,
                start = PositionImpl(
                    line = start.line - 1,
                    character = start.charPositionInLine,
                ),
                end = PositionImpl(
                    line = end.line - 1,
                    character = end.charPositionInLine
                ),
                null,
                depth = depth
            )
        )
    }

    private fun popMismatch(startCommand: String, start: Token, newStart: Token) {
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand,
                endToken = null,
                startIndex = start.startIndex,
                endIndex = max(start.stopIndex, newStart.startIndex - 1),
                start = PositionImpl(
                    line = start.line - 1,
                    character = start.charPositionInLine
                ),
                end = PositionImpl(
                    line = newStart.line - 1,
                    character = maxOf(0, newStart.charPositionInLine - 1),
                ),
                null,
                depth = depth
            )
        )
    }

    companion object {
        private val DOIF = intArrayOf(token("doif"))
        private val ESCN = intArrayOf(token("escn"))
        private val ENUM = intArrayOf(
            token("enum"),
            token("epas"),
            token("etch"),
            token("esee"),
            token("econ")
        )
        private val LOOP = intArrayOf(token("loop"))
        private val SUBR = intArrayOf(token("subr"))
        private val REPS = intArrayOf(token("reps"))


        // Endings
        private val ENDI = token("endi")
        private val EVER = token("ever")
        private val NEXT = token("next")
        private val NSCN = token("nscn")
        private val REPE = token("repe")
        private val RETN = token("retn")
        private val UNTL = token("untl")

        private val hasNextNext = arrayOf(token("PRAY"), token("HIST"))
    }
}