package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.collectors.ParserItem
import com.bedalton.creatures.caos.collectors.end
import com.bedalton.creatures.caos.collectors.start
import com.bedalton.creatures.caos.server.HasRange
import com.bedalton.creatures.caos.server.Range
import com.bedalton.creatures.caos.server.RangeWithIndexImpl
import kotlin.math.max
import kotlin.math.min


internal fun ParserItem<*>.isComment(): Boolean {
    return this is ParserItem.Comment || this is ParserItem.Caos2Comment
}


internal fun ParserItem<*>.isWhitespace(): Boolean {
    return this is ParserItem.NewLine || this is ParserItem.Spaces
}


internal fun <T : HasRange> List<T>.inRange(parent: Range): List<T> {
    return this.filter {
        com.bedalton.creatures.caos.server.inRange(it.textRange, parent)
    }
}

internal fun combine(first: ParserItem.NewLine, second: ParserItem.NewLine): ParserItem.NewLine {
    val firstText: String
    val secondText: String
    val min = if (first.textRange.startIndex < second.textRange.startIndex) {
        firstText = first.text
        secondText = second.text
        first.start
    } else {
        firstText = second.text
        secondText = first.text
        second.start
    }
    val max = if (first.textRange.endIndex < second.textRange.endIndex) {
        first.end
    } else {
        second.end
    }
    return ParserItem.NewLine(
        textRange = RangeWithIndexImpl(
            start = min,
            end = max,
            startIndex = min(first.textRange.startIndex, second.textRange.startIndex),
            endIndex = max(first.textRange.endIndex, second.textRange.endIndex),
        ),
        firstText + secondText
    )
}

internal fun ParserItem<*>?.isWhitespaceOrComment(): Boolean {
    return this?.isWhitespace() == true || this?.isComment() == true
}
