@file:Suppress("unused")

package com.bedalton.creatures.caos.utils

import kotlin.contracts.ExperimentalContracts
import kotlin.contracts.contract

fun String?.nullIfEmpty(): String? {
    return if (this.isNullOrBlank())
        null
    else
        this
}

fun <T> Collection<T>.filterNotNull(): List<T> {
    return this.mapNotNull { it }
}

fun <R, T : Collection<R>> T?.nullIfEmpty(): T? {
    if (this == null || isEmpty())
        return null
    return this
}

fun <T> Array<T>?.nullIfEmpty() : Array<T>? {
    if (this == null || this.isEmpty())
        return null
    return this
}

fun <R, T : Collection<R>> T?.nullIfEmpty(filterNullsFirst: Boolean): T? {
    if (this == null)
        return null
    val isEmpty = if (filterNullsFirst)
        this.filterNotNull().isEmpty()
    else
        this.isEmpty()
    return if (isEmpty) null else this
}

@OptIn(ExperimentalContracts::class)
fun String?.isNotNullOrEmpty(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrEmpty != null)
    }
    return this != null && this.isNotEmpty()
}

@OptIn(ExperimentalContracts::class)
fun String?.isNotNullOrBlank(): Boolean {
    contract {
        returns(true) implies (this@isNotNullOrBlank != null)
    }
    return this != null && this.isNotBlank()
}

fun <T> T?.orElse(defaultValue: T): T {
    return this ?: defaultValue
}

fun <T> T?.orElse(defaultValue: () -> T): T {
    return this ?: defaultValue()
}


fun Boolean?.orFalse(): Boolean {
    return this ?: false
}

fun Boolean?.orTrue(): Boolean {
    return this ?: true
}

fun String?.nullIfBlank(): String? = if (this.isNullOrBlank()) null else this

fun <T, R> Collection<T>.minus(elements: Collection<T>, selector: (T) -> R?) =
    filter { t -> elements.none { selector(it) == selector(t) } }


fun <T> MutableList<T>.insertFront(item: T): MutableList<T> {
    if (this.isEmpty())
        this.add(item)
    else
        this.add(0, item)
    return this
}

fun <T> MutableList<T>.insertFront(more: List<T>): MutableList<T> {
    if (this.isEmpty())
        this.addAll(more)
    else
        this.addAll(0, more)
    return this
}
fun <T> MutableList<T>.insertFront(more: Array<T>): MutableList<T> {
    if (this.isEmpty())
        this.addAll(more)
    else
        this.addAll(0, more.toList())
    return this
}


infix fun String?.like(other: String?): Boolean {
    if (this == null || other == null)
        return false
    return this.equals(other, ignoreCase = true)
}

infix fun String?.likeAny(other: Collection<String>?): Boolean {
    if (this == null || other == null)
        return false
    return other.any { this.equals(it, ignoreCase = true) }
}

infix fun String?.likeAny(other: Set<String>?): Boolean {
    if (this == null || other == null)
        return false
    return other.any { this.equals(it, ignoreCase = true) }
}

infix fun String?.notLikeAny(other: Set<String>?): Boolean {
    if (this == null || other == null)
        return false
    return other.none { this.equals(it, ignoreCase = true) }
}

infix fun String?.notLike(other: String?): Boolean {
    if (this == null || other == null)
        return false
    return !this.equals(other, ignoreCase = true)
}


