/**
 * Compares the similarity between two strings using an n-gram comparison method.
 * The grams default to length 2.
 * @param string1In The first string to compare.
 * @param string2In The second string to compare.
 * @param gramSize The size of the grams. Defaults to length 2.
 */
fun stringDistance(string1In: String?, string2In: String?, gramSize: Int = 2): Float {

    // Internal function to split string into overlapping chunks
    fun getNGrams(stringIn: String, nGramLength: Int): Array<String> {
        val stringPadded = "".padStart(nGramLength - 1, ' ') + stringIn.lowercase() + "".padStart(nGramLength - 1, ' ')
        val nGrams = Array(stringPadded.length - nGramLength + 1) { "" }
        for (i in nGrams.indices) {
            nGrams[i] = stringPadded.slice(i until i + nGramLength)
        }
        return nGrams
    }

    if (string1In.isNullOrEmpty() || string2In.isNullOrEmpty())
        return 0.0f

    //Order the strings by length so the order they're passed in doesn't matter
    //and so the smaller string's ngrams are always the ones in the set
    val string1 = if (string1In.length < string2In.length) string1In else string2In
    val string2 = if (string1In.length < string2In.length) string2In else string1In

    val pairs1 = getNGrams(string1, gramSize)
    val pairs2 = getNGrams(string2, gramSize)
    val set = pairs1.toMutableSet()

    val total = pairs2.size
    var hits = 0
    for (item in pairs2) {
        if (set.remove(item)) {
            hits++
        }
    }
    return 1 - (hits / total.toFloat())
}

val <T> T?.className: String? get() {
    return this?.let {
        it::class.simpleName
    }
}

internal expect val <T> T?.propertyNames: Array<String>

fun <T> MutableList<T>.splice(index:Int, itemCount:Int) : List<T> {
    val slice = slice(index until index + itemCount)
    for (i in index + itemCount - 1 downTo index) {
        removeAt(i)
    }
    return slice
}