@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.libs.ICaosCommand
import com.bedalton.creatures.caos.server.RangeWithIndex
import com.bedalton.creatures.caos.server.RangeWithIndexImpl
import kotlin.js.JsExport
import kotlin.js.JsName
import kotlin.math.max
import kotlin.math.min

/**
 * Check if a range is empty, i.e. start and end are the same
 */
fun RangeWithIndex.empty(): Boolean {
    return endIndex <= startIndex
}

/**
 * Reference to a command within a ParseResult object
 */
@JsExport
data class CommandReference(
    /**
     * CAOS Command documentation object
     */
    @JsName("command")
    val command: ICaosCommand,
    /**
     * Command string for this command use
     */
    @JsName("commandString")
    val commandString: String = command.command,
    /**
     * The line where this referenced command starts
     */
    @JsName("line")
    val line: Int,
    /**
     * The column on the line where this command call starts
     */
    @JsName("column")
    val column: Int,
    /**
     * Index into the ParseResults command array where this referenced call resides
     */
    @JsName("commandCallIndex")
    val commandCallIndex: Int
) {

    /**
     * Constructs a command reference from a command call, when given its index in the commands array
     */
    @JsName("withCommandCall")
    internal constructor(commandCall: CommandCall, callIndex: Int): this(
        command = commandCall.command,
        line = commandCall.textRange.start.line,
        column = commandCall.textRange.start.character,
        commandCallIndex = callIndex
    )
}

/**
 * Combine ranges taking the extremes between the two
 */
internal operator fun RangeWithIndex.plus(other: RangeWithIndex): RangeWithIndex {
    return RangeWithIndexImpl(
        startIndex = min(startIndex, other.startIndex),
        endIndex = max(endIndex, other.endIndex),
        start = if (startIndex < other.startIndex) start else other.start,
        end = if (endIndex > other.endIndex) end else other.end,
        parserIndex = parserIndex
    )
}