package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosWhitespaceParser
import com.bedalton.creatures.caos.antlr.CaosWhitespaceParserBaseListener
import com.bedalton.creatures.caos.server.RangeWithIndexImpl

class WhitespaceCollector: CaosWhitespaceParserBaseListener() {


    private val mWhitespace = mutableListOf<ParserItem<*>>()

    val whitespace: List<ParserItem<*>>
        get() = mWhitespace

    override fun enterSpace(ctx: CaosWhitespaceParser.SpaceContext) {
        super.enterSpace(ctx)
        mWhitespace.add(
            ParserItem.Spaces(
                RangeWithIndexImpl(ctx.start!!, ctx.stop!!),
                ctx.trueText
            )
        )
    }


    override fun enterNewline(ctx: CaosWhitespaceParser.NewlineContext) {
        super.enterNewline(ctx)
        mWhitespace.add(
            ParserItem.NewLine(
                RangeWithIndexImpl(ctx.start!!, ctx.stop!!),
                ctx.trueText
            )
        )
    }

    companion object {
        private const val TAG = "WhitespaceCollector"
    }
}