package com.bedalton.creatures.caos.utils


internal val NEWLINE_REGEX = "\r?\n".toRegex()
private const val ESCAPE_SEQUENCE = ";;#\\@(_x.x_)@/#;;"

private fun superUnescape(string: String): String {
    // ensure that escape sequence is not found in string first
    var escape = ESCAPE_SEQUENCE
    while(string.contains(escape)) {
        escape = "!x($escape)x!"
    }
    return string.replace("\\\\", escape)
        .replace("\\n", "\n")
        .replace("\\r", "\r")
        .replace("\\\"", "\"")
        .replace("\\'", "'")
        .replace("\\t", "\t")
        .replace("\\b", "\b")
        .replace("\\ ", " ")
        .replace("\\", "") // remove useless escape
        .replace(escape, "\\")
        .replace(NEWLINE_REGEX, "\r\n")
}

internal fun String.stripSurroundingQuotes(trim:Int = 1): String {
    if (isEmpty())
        return ""
    if (length == 1) {
        return if (this[0] == '"' || this[0] == '\'')
            ""
        else
            this
    }
    var string = if (trim > 0) this.trim() else this
    // Trim off whitespace and quotes as needed
    if (string.startsWith('"') && string.endsWith('"'))
        string = string.substring(1, string.lastIndex)
    else if (string.startsWith('\'') && string.endsWith('\''))
        string = string.substring(1, string.lastIndex)
    return superUnescape(string).let {
        if (trim > 1)
            it.trim()
        else
            it
    }
}

@Suppress("RegExpUnnecessaryNonCapturingGroup")
private val pathRegex = "^((?:\"(?:(?:\\\\).|[^\"])*\")|(?:(?:\\\\.|[^\"\\s])+))(.*)".toRegex()

internal fun splitQuoted(string: String): List<String> {
    val out = mutableListOf<String>()
    var working = string.trim()
    while (working.isNotBlank()) {
        val values = pathRegex.matchEntire(working)
            ?.groupValues
            ?: break
        out.add(values[1].stripSurroundingQuotes())
        working = values.getOrNull(2)
            .nullIfEmpty()
            ?.trim()
            ?: break
    }
    return out
}