internal class CommandWalker(
    private val lib: CaosLib,
    private val originalText: String,
    private val tokens: Array<ParserItem<*>>,
    private val checkCancelled: () -> Unit,
) {

    private val variant: String by lazy { lib.variantCode }
    private val closestByVariant = getClosestByVariantFilter(lib.variantCode)
    val commandCalls: Array<CommandCall> get() = mCommands.toTypedArray()
    val looseTokens: Array<ParserItem<*>> get() = loose.toTypedArray()
    val comments = mutableListOf<ParserItem.Comment>()
    val caos2Comments = mutableListOf<ParserItem.Caos2Comment>()
    val equalityStatements
        get() = mCommands
            .filter { it.type == ValueType.CONDITION.value }
            .map {

                val start = it.arguments.getOrNull(0)?.textRange ?: it.textRange
                val last = it.arguments.lastOrNull()?.textRange ?: it.textRange
                val range = RangeWithIndexImpl(
                    startIndex = start.startIndex,
                    endIndex = last.endIndex + 1,
                    start = start.start,
                    end = last.end
                )
                EqualityStatement(
                    textRange = range,
                    first = it.arguments.getOrNull(0),
                    second = it.arguments.getOrNull(2),
                    eqToken = it.arguments.getOrNull(1)?.parserItem as? ParserItem.EqOp,
                    it.containingCommand,
                    it.parameter ?: CONDITION_PARAMETER
                ) {
                    originalText.substring(range.startIndex, range.endIndex).trim()
                }
            }
            .sortedBy { it.startIndex }
            .toTypedArray()

    val equalityStatementRanges
        get() = getEqualityStatementRanges(equalityStatements, tokens)
            .toTypedArray()

    private val stops = StopCommands[lib.variantCode]!!
    private val mCommands: MutableList<CommandCall> = mutableListOf()
    private val working: MutableList<CommandCall> = mutableListOf()
    private val waiting: MutableList<ICaosParameter> = mutableListOf()
    private val loose: MutableList<ParserItem<*>> = mutableListOf()
    private var commandTokens: Array<Pair<Int, ParserItem.CommandToken>> = arrayOf()
    private var line = 0
    private var columnInLine: Int = 0
    private var textPositionInFile = 0
    private var tokenIndex = 0
    private var newline = true

    init {
        try {
            walk()
        } catch (_: ParseCancelledException) {

        }
        //Log.i(TAG, "Tokens: ${tokens.joinToString(" ") { it.value.toString() }}")
    }

    private fun walk() {
        val lastIndex = tokens.lastIndex
        while (tokenIndex <= lastIndex) {
            val token = tokens[tokenIndex]
            if (working.lastOrNull()?.done == false && line != token.textRange.start.line && token is ParserItem.CommandToken && !nextCommandValid(
                    token
                )
            ) {
                waiting.clear()
                working.clear()
                line = token.textRange.start.line
                if (popTokens()) {
                    continue
                }
            }
            if (token !is ParserItem.EqJoin) {
                while (waiting.firstOrNull() == EQ_JOIN) {
                    waiting.removeFirst()
                }
            }
            if (token is ParserItem.CommandToken) {
                if (waiting.firstOrNull()?.typeId == ValueType.TOKEN.value) {
                    val altered = ParserItem.TokenVal(
                        token.textRange,
                        value = token.value
                    )
                    tokens[tokenIndex] = altered
                    pushArgument(altered)
                } else {
                    pushCommandToken(token)
                }
            } else if (token is ParserItem.TokenVal) {
                when (waiting.firstOrNull()?.typeId) {
                    ValueType.TOKEN.value -> {
                        pushArgument(token)
                    }
                    ValueType.PICT_DIMENSION.value -> {
                        val altered = ParserItem.DdePictVal(
                            token.textRange,
                            value = Pair(token.value[0].code, token.value.getOrNull(2)?.code ?: -1),
                            token.text
                        )
                        tokens[tokenIndex] = altered
                        pushArgument(altered)
                    }
                    else -> {
                        pushArgument(token)
                        loose.add(token)
                    }
                }
            } else if (token is ParserItem.EqJoin) {
                if (waiting.firstOrNull() == EQ_JOIN) {
                    //waiting.removeFirstOrNull()
                    if (working.firstOrNull()?.command == ConditionCommand) {
                        working.removeFirst()
                        done()
                    } else if (working.firstOrNull()?.done == true) {
                        done()
                    }
                    waiting.addAll(conditionParameters)
                    pushCommand(
                        condition(
                            working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
                            waiting.firstOrNull() ?: CONDITION_PARAMETER,
                            token.textRange
                        )
                    )
                } else {
                    loose.add(token)
                }
            } else if (token is ParserItem.Comment) {
                comments.add(token)
            } else if (token is ParserItem.Caos2Comment) {
                caos2Comments.add(token)
            } else {
                if (!popTokens()) {
                    val altered: ParserItem<*> = if (token is ParserItem.ByteStringVal) {
                        // If type is ByteString, but a string is expected
                        // Convert to C1 string
                        if (waiting.firstOrNull()?.typeId == ValueType.C1_STRING.value || waiting.firstOrNull()?.typeId == ValueType.STRING.value) {
                            ParserItem.C1eStringVal(
                                token.textRange,
                                value = token.value
                            )
                        } else
                            token
                    } else if (token is ParserItem.C1eStringVal) {
                        // If type is C1 String, but a byte-string or animation is expected
                        // Convert to byte string
                        if (waiting.firstOrNull()?.typeId == ValueType.BYTE_STRING.value || waiting.firstOrNull()?.typeId == ValueType.ANIMATION.value) {
                            ParserItem.ByteStringVal(
                                token.textRange,
                                value = token.value
                            )
                        } else
                            token
                    } else {
                        token
                    }
                    pushArgument(altered)
                }
            }
            newline = token.textRange.end.line != line
            line = token.textRange.end.line
            columnInLine = token.textRange.end.character
            textPositionInFile = token.textRange.endIndex
            tokenIndex++
            checkCancelled()
        }
        knock(null)
        finalize()
    }

    private fun popTokens(): Boolean {
        if (commandTokens.isEmpty())
            return false
        val temp = commandTokens.copyOf()
        val length = temp.size
        for (i in 0 until length) {
            commandTokens = emptyArray()
            for (j in i until length) {
                if (pushCommandToken(temp[j].second)) {
                    tokenIndex -= j - 1
                    commandTokens = emptyArray()
                    for (k in 0 until j) {
                        loose.add(temp[k].second)
                    }
                    val startToken = temp[j].second
                    line = startToken.textRange.end.line
                    columnInLine = startToken.textRange.end.character
                    return true
                }
            }
        }
        commandTokens = emptyArray()
        loose.addAll(temp.map { it.second })
        return false
    }

    private fun nextCommandValid(token: ParserItem.CommandToken): Boolean {
        var commandTokens = commandTokens.copyOf()
        /*
         * Clear unmatched tokens when they are on different lines. May cause false parsing errors,
         * But it would be weird to split command words onto different lines
         */
        if (token.textRange.start.line != line && commandTokens.isNotEmpty()) {
            //Log.i(TAG, "Tokens left on line change. Clearing tokens: [${commandTokens.joinToString { it.second.value }}]")
            loose.addAll(commandTokens.map { it.second })
            return false
        }
        // Append this new token to the running list
        commandTokens += Pair(token(token.value.lowercase()), token)
        while (commandTokens.size > 3) {
            //Log.i(TAG, "Too many tokens in waiting pool... removing: '${commandTokens.first().second.value}'")
            val badCommand = commandTokens.first().second
            loose.add(badCommand)
            commandTokens = commandTokens.sliceArray(1 until commandTokens.size)
        }

        // Get command type based on what is going on
        val commandType = when {
            waiting.isEmpty() -> CommandType.COMMAND
            waiting.firstOrNull()?.typeId == ValueType.VARIABLE.value -> CommandType.LVALUE
            else -> CommandType.RVALUE
        }

        // Find a matching command for tokens
        val commandSearchTokens = commandTokens.map { it.first }.toIntArray()
        // Command bias for commands where there are two commands with the same token
        val bias: ValueType = waiting.firstOrNull()
            ?.typeId
            ?.let { typeId -> ValueType.fromIntValue(typeId) }
            ?: ValueType.ANY

        // Get command if any from library
        val (_, _) = lib[commandType][commandSearchTokens, bias]
        // Wait until all available token slots have been filled to make sure
        // fallback command does not return value before actual variant can
            ?: getFallback(commandType, commandSearchTokens)
            ?: return false
        return true

    }

    private fun pushCommandToken(token: ParserItem.CommandToken): Boolean {
        // Clear pending if it is a for sure start of a new command
        knock(token)
        /*
         * Clear unmatched tokens when they are on different lines. May cause false parsing errors,
         * But it would be weird to split command words onto different lines
         */
        if (token.textRange.start.line != line && commandTokens.isNotEmpty()) {
            //Log.i(TAG, "Tokens left on line change. Clearing tokens: [${commandTokens.joinToString { it.second.value }}]")
            loose.addAll(commandTokens.map { it.second })
            commandTokens = emptyArray()
        }
        // Append this new token to the running list
        commandTokens += Pair(token(token.value.lowercase()), token)
        while (commandTokens.size > 3) {
            //Log.i(TAG, "Too many tokens in waiting pool... removing: '${commandTokens.first().second.value}'")
            val badCommand = commandTokens.first().second
            loose.add(badCommand)
            commandTokens = commandTokens.sliceArray(1 until commandTokens.size)
        }

        // Get command type based on what is going on
        val commandType = when {
            waiting.isEmpty() -> CommandType.COMMAND
            waiting.firstOrNull()?.typeId == ValueType.VARIABLE.value -> CommandType.LVALUE
            else -> CommandType.RVALUE
        }

        // Find a matching command for tokens
        val commandSearchTokens = commandTokens.map { it.first }.toIntArray()
        // Command bias for commands where there are two commands with the same token
        val bias: ValueType = waiting.firstOrNull()
            ?.typeId
            ?.let { typeId -> ValueType.fromIntValue(typeId) }
            ?: ValueType.ANY

        // Get command if any from library
        val (command, tokensUsed) = lib[commandType][commandSearchTokens, bias]
        // Wait until all available token slots have been filled to make sure
        // fallback command does not return value before actual variant can
            ?: getFallback(commandType, commandSearchTokens)
            ?: return false

        val startToken = commandTokens.first().second.textRange
        val endToken = commandTokens[tokensUsed - 1].second.textRange
        val commandTokenRange = RangeWithIndexImpl(
            startIndex = startToken.startIndex,
            endIndex = endToken.endIndex,
            start = startToken.start,
            end = endToken.end,
            parserIndex = token.parserIndex
        )
        val theseTokens = if (tokensUsed < commandTokens.size) {
            commandTokens.sliceArray(0 until tokensUsed)
        } else {
            commandTokens
        }

        // Remove tokens matched to command
        commandTokens = if (tokensUsed < commandTokens.size) {
            commandTokens.sliceArray(tokensUsed until commandTokens.size)
        } else {
            arrayOf()
        }

        val parameter = waiting.firstOrNull()
        // Add command and parameters to waiting and working
        val commandJS = command.toJsCommand(variant)
        val theseTokensArray = theseTokens.map { it.second }.toTypedArray()
        val commandCall = CommandCall(
            type = if (commandType == CommandType.LVALUE) ValueType.VARIABLE.value else command.returnTypeId,
            command = commandJS,
            tokenTextRange = commandTokenRange,
            inVariant = command.variants.indexOf(variant) >= 0,
            textRange = commandTokenRange,
            tokens = theseTokensArray,
            parameter = parameter,
            inEqualityExpression = working.firstOrNull()?.type == ValueType.CONDITION.value || parameter == EQ_JOIN || parameter == EQ_OP || parameter == EQ_FIRST_PARAM || parameter == EQ_SECOND_PARAM,
            containingCommand = working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
            callType = commandType
        )
        //Log.i(TAG, "Variant:$variant, [${command.command}](${command.variants}); InVariant: ${commandCall.inVariant}")
        if (command.command == "SETV") {
            val nextToken = (tokens.getOrNull(tokenIndex + 1) as? ParserItem.CommandToken)?.value?.uppercase()
            if (nextToken in leftValueNoVar) {
                val altered: CommandCall = commandCall.copy(
                    command = commandJS.copy(
                        parameters = commandJS.parameters.dropLast(1).toTypedArray()
                    )
                )
                pushCommand(altered)
                addParameters(altered.command.parameters, commandTokenRange)
                return true
            }
        }

        pushCommand(commandCall)
        if (commandJS.parameters.isEmpty()) {
            done()
        } else {
            //Log.i(TAG, "Parameters for: ${commandJS.command} == [${commandJS.parameters.joinToString { it.name }}]")
            addParameters(commandJS.parameters, commandTokenRange)
        }
        return true
    }

    private fun addParameters(
        parameters: Array<ICaosParameter>,
        textRange: RangeWithIndex,
    ) {
        for (parameter in parameters.reversed()) {
            waiting.insertFront(parameter)
            if (parameter.typeId == ValueType.CONDITION.value) {
                pushCommand(
                    condition(
                        working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) },
                        waiting.firstOrNull() ?: CONDITION_PARAMETER,
                        textRange
                    )
                )
                waiting.insertFront(conditionParameters)
            }
        }
        //Log.i(TAG, "Parameters: [${waiting.joinToString { it.formatted }}]")
    }


    /*private fun addParameters(parameters: Array<ICaosParameter>, textRange: TextRange) {
        val parametersActual = parameters.flatMap { parameter ->
            if (parameter.typeId == ValueType.CONDITION.value) {
                working.insertFront(condition(textRange))
                conditionParameters
            } else {
                listOf(parameter)
            }
        }
        waiting.insertFront(parametersActual)
    }*/

    private fun done() {
        val token = tokens[tokenIndex]
        textPositionInFile = token.textRange.endIndex
        while (true) {
            val commandCall = working.removeFirstOrNull()
                ?: return
            if (!commandCall.done) {
                working.insertFront(commandCall)
                break
            }
        }
    }

    private fun knock(item: ParserItem.CommandToken?) {
        //Log.i(TAG, "Item: ${item?.value}(${token(item?.value ?: ",,,,")}) in Stops? ${token(item?.value ?: ",,,,") in stops}")
        if (item == null || item.token in stops && (working.isNotEmpty() || waiting.isNotEmpty())) {
//            Log.i(TAG, "Knocking all tokens at: '${item?.value}'")
            working.clear()
            waiting.clear()
            if (!popTokens()) {
                loose.addAll(commandTokens.map { it.second })
            }
        }
    }

    private fun pushCommand(commandCall: CommandCall) {
        mCommands.add(commandCall)
        val parameter = waiting.removeFirstOrNull()
        if (parameter != null) {
            //Log.i(TAG, "Command ${commandCall.command.command} is for parameter: ${parameter.name}")
            working.firstOrNull()?.let { workingCommand ->
                workingCommand.arguments += commandCall
                done()
            }
        } else if (!commandCall.command.isCommand) {
            Log.e(TAG, "L/RValue command '${commandCall.command.command}' pushed without parameter")
        } else {
            //Log.i(TAG, "Pushing command ${commandCall.command.command}")
        }
        working.insertFront(commandCall)
    }

    private fun pushArgument(item: ParserItem<*>) {
        //Log.i(TAG, "Waiting: [${waiting.joinToString { it.formatted }}]")
        val parameter = waiting.removeFirstOrNull()
        if (parameter == null) {
            loose.add(item)
            return
        }

        val command: CommandCall = working.firstOrNull()
            ?: throw Exception("Parameters found in waiting without working command: [${waiting.joinToString { it.name }}]")

        command.arguments += ParserItemArgument(
            textRange = item.textRange,
            parameter = parameter,
            type = item.actualType,
            text = item.text,
            inEqualityExpression = working.firstOrNull()?.type == ValueType.CONDITION.value || parameter == EQ_JOIN || parameter == EQ_OP || parameter == EQ_FIRST_PARAM || parameter == EQ_SECOND_PARAM,
            parserItem = item,
            containingCommand = working.firstOrNull()?.let { CommandReference(it, mCommands.lastIndex) }
        ) as Argument
        //Log.i(TAG, "Command [${command.command.command}] Arguments: [${command.arguments.joinToString { it.text }}]")
        if (waiting.firstOrNull() == EQ_JOIN) {
            if (tokens.getOrNull(tokenIndex + 1) !is ParserItem.EqJoin) {
                waiting.removeFirstOrNull()
                if (working.firstOrNull()?.command == ConditionCommand) {
                    done()
                } else {
                    done()
                }
            }
        } else if (command.done) {
            done()
        }
    }

    /**
     * Gets a fallback command from the other variants
     * Used to help find where a command is used out of variant
     * This helps parser recover
     */
    private fun getFallback(commandType: CommandType, commandSearchTokens: IntArray): Pair<CaosCommand, Int>? {
        var tempTokens = commandSearchTokens.copyOf()
        var result: Pair<CaosCommand, Int>? = null
        var i = 1
        while (tempTokens.size < 3) {
            result = lib[commandType][commandSearchTokens]
            if (result != null)
                break
            else {
                val next = tokens.getOrNull(tokenIndex + i++)
                if (next !is ParserItem.CommandToken || next.value.length != 4) {
                    break
                }
                tempTokens += token(next.value)
            }
        }
        if (result != null) {
            tokenIndex += i
        }

        return CaosLibs.commands(commandSearchTokens).filterByType(commandType)?.let { (commands, _) ->
            if (commands.isNotEmpty()) {
                closestByVariant(commands)?.let { command ->
                    Pair(command, commandSearchTokens.size)
                }
            } else {
                null
            }
        }
    }

    private fun finalize() {
        for (i in mCommands.indices) {
            val commandCall = mCommands[i]
            // Calculate new end if any
            val trueEnd = endEnd(commandCall)
            if (trueEnd != null) {
                commandCall.textRange = (commandCall.textRange as RangeWithIndexImpl).copy(
                    endIndex = trueEnd.endIndex,
                    end = trueEnd.end
                )
            }
        }
    }

    private fun endEnd(commandCall: CommandCall): RangeWithIndex? {
        val lastArgument = commandCall
            .arguments
            .nullIfEmpty()
            ?.maxByOrNull { it.endIndex }
            ?: return null
        return if (lastArgument !is CommandCall) {
            lastArgument.textRange
        } else {
            endEnd(lastArgument) ?: lastArgument.textRange
        }

    }


    companion object {
        private const val TAG = "CommandWalker"

        fun getEqualityStatementRanges(equalityStatementIn: Array<EqualityStatement>, tokens: Array<ParserItem<*>>): List<RangeWithIndex> {
            // Sort statements
            val equalityStatements = equalityStatementIn.sortedBy { it.startIndex }

            // If no statements, nothing to return
            if (equalityStatements.isEmpty()) {
                return emptyList()
            }

            // Sort Items and get only joins
            val joins = tokens
                .sortedBy { it.startIndex }
                .filterIsInstance<ParserItem.EqJoin>()
                .toMutableList()

            // List of calculated ranges
            val out = mutableListOf<RangeWithIndex>()

            // Index in eq statements list
            var i = 0


            while (i < equalityStatements.size) {
                val statement = equalityStatements[i++]

                // get the furthest eq item
                var last = statement.second
                    ?: statement.eqToken
                    ?: statement.first


                // If no eq item, skip add default range and continue
                if (last == null) {
                    out.add(statement.textRange)
                    continue
                }

                // Make sure joins come after the current eq statement
                // If not, the EQ statement is loose somewhere
                var join = joins.firstOrNull()
                while (join != null && join.startIndex < last.endIndex) {
                    joins.removeFirst()
                    join = joins.firstOrNull()
                }

                // If there are no joins left, simply add the eq statement's range
                if (join == null) {
                    out.add(statement.textRange)
                    continue
                }

                // Create starting range
                var range = statement.textRange

                // Loop through consecutive join+eq statement pairs
                join@while (join != null && last != null && isConsecutive(last, join)) {
                    joins.removeFirst()
                    val next = equalityStatements[i++]
                    range = statement.textRange + next.textRange
                    last = next.second ?: next.eqToken ?: next.first
                            ?: break@join
                    join = joins.firstOrNull()
                        ?: break@join
                }
                out.add(range)
            }
            return out
        }
    }

}


private fun isConsecutive(first: CaosItem, second: CaosItem): Boolean {
    val firstIndex = when(first) {
        is ParserItem<*> -> first.parserIndexEnd
        is ParserItemArgument -> first.parserIndexEnd
        is CommandCall -> first.parserIndexEnd
        is EqualityStatement -> first.parserIndexEnd
        else -> first.textRange.parserIndex
    }
        ?: return false
    val secondIndex = when(second) {
        is ParserItem<*> -> second.parserIndexStart
        is ParserItemArgument -> second.parserIndexStart
        is CommandCall -> second.parserIndexStart
        is EqualityStatement -> second.parserIndexStart
        else -> second.textRange.parserIndex
    }
        ?: return false
    return firstIndex + 1 == secondIndex
}

data class CommandCallJs (
    override val type: Int,
    @JsName("command")
    val command: ICaosCommand,
    @JsName("arguments")
    var arguments: Array<Argument>,
    @JsName("tokenTextRange")
    val tokenTextRange: RangeWithIndex,
    @JsName("inVariant")
    val inVariant: Boolean,
    override val textRange: RangeWithIndex,
    override val parameter: ICaosParameter?,
    override var inEqualityExpression: Boolean,
    override val containingCommand: CommandReference?,
    @JsName("tokens")
    val tokens: Array<ParserItem.CommandToken>,
    @JsName("callType")
    val callType: CommandType,
    @JsName("isRvalue")
    val isRvalue: Boolean = callType == CommandType.RVALUE,
    @JsName("isLvalue")
    val isLvalue: Boolean = callType == CommandType.LVALUE,
    @JsName("isCommand")
    val isCommand: Boolean = callType == CommandType.COMMAND,
    override val parserItem: ParserItem.CompoundCommandToken = ParserItem.CompoundCommandToken(tokens),
    override val text: String = stitch(*tokens, *arguments),
    val commandString: String = command.command,
    override val parserIndexStart: Int?,
    override val parserIndexEnd: Int?,
): HasRange, Argument, CaosItem {

    constructor(commandCall: CommandCall): this (
        type = commandCall.type,
        command = commandCall.command,
        arguments = commandCall.arguments,
        tokenTextRange = commandCall.tokenTextRange,
        inVariant = commandCall.inVariant,
        textRange = commandCall.textRange,
        parameter = commandCall.parameter,
        inEqualityExpression = commandCall.inEqualityExpression,
        containingCommand = commandCall.containingCommand,
        tokens = commandCall.tokens,
        callType = commandCall.callType,
        isRvalue = commandCall.isRvalue,
        isLvalue = commandCall.isLvalue,
        isCommand = commandCall.isCommand,
        parserItem = commandCall.parserItem,
        text = commandCall.text,
        commandString = commandCall.commandString,
        parserIndexStart = commandCall.parserIndexStart,
        parserIndexEnd = commandCall.parserIndexEnd
    )


    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CommandCallJs) return false

        if (type != other.type) return false
        if (command != other.command) return false
        if (!arguments.contentEquals(other.arguments)) return false
        if (tokenTextRange != other.tokenTextRange) return false
        if (inVariant != other.inVariant) return false
        if (textRange != other.textRange) return false
        if (parameter != other.parameter) return false
        if (inEqualityExpression != other.inEqualityExpression) return false
        if (containingCommand != other.containingCommand) return false
        if (!tokens.contentEquals(other.tokens)) return false
        if (callType != other.callType) return false
        if (isRvalue != other.isRvalue) return false
        if (isLvalue != other.isLvalue) return false
        if (isCommand != other.isCommand) return false
        if (parserItem != other.parserItem) return false
        if (text != other.text) return false
        if (commandString != other.commandString) return false

        return true
    }

    override fun hashCode(): Int {
        var result = type
        result = 31 * result + command.hashCode()
        result = 31 * result + arguments.contentHashCode()
        result = 31 * result + tokenTextRange.hashCode()
        result = 31 * result + inVariant.hashCode()
        result = 31 * result + textRange.hashCode()
        result = 31 * result + (parameter?.hashCode() ?: 0)
        result = 31 * result + inEqualityExpression.hashCode()
        result = 31 * result + (containingCommand?.hashCode() ?: 0)
        result = 31 * result + tokens.contentHashCode()
        result = 31 * result + callType.hashCode()
        result = 31 * result + isRvalue.hashCode()
        result = 31 * result + isLvalue.hashCode()
        result = 31 * result + isCommand.hashCode()
        result = 31 * result + parserItem.hashCode()
        result = 31 * result + text.hashCode()
        result = 31 * result + commandString.hashCode()
        return result
    }
}

@JsExport
@JsName("CommandCall")
data class CommandCall(
    override val type: Int,
    @JsName("command")
    val command: ICaosCommand,
    @JsName("arguments")
    var arguments: Array<Argument> = emptyArray(),
    @JsName("tokenTextRange")
    val tokenTextRange: RangeWithIndex,
    @JsName("inVariant")
    val inVariant: Boolean,
    override var textRange: RangeWithIndex,
    override val parameter: ICaosParameter?,
    override var inEqualityExpression: Boolean,
    override val containingCommand: CommandReference?,
    @JsName("tokens")
    val tokens: Array<ParserItem.CommandToken>,
    @JsName("callType")
    val callType: CommandType
) : HasRange, Argument, CaosItem {

    val isRvalue get() = callType == CommandType.RVALUE
    val isLvalue get() = callType == CommandType.LVALUE
    val isCommand get() = callType == CommandType.COMMAND

    private val parameterCount = command.parameters.size

    internal val done: Boolean get() = arguments.size >= parameterCount

    override val parserItem by lazy {
        ParserItem.CompoundCommandToken(tokens)
    }

    override val text get() = stitch(this.parserItem, *arguments)

    val commandString get() = command.command

    internal val missingParameters: Array<ICaosParameter>
        get() = if (arguments.size >= parameterCount) {
            emptyArray()
        } else {
            command.parameters.sliceArray(arguments.size until parameterCount)
        }

    override val parserIndexStart: Int?
        get() = tokens
            .firstOrNull()
            ?.parserIndex
            ?: textRange.parserIndex

    override val parserIndexEnd: Int?
        get() = arguments
            .lastOrNull()
            ?.let {
                when (it) {
                    is CommandCall -> it.parserIndexEnd
                    is ParserItemArgument -> it.parserIndexEnd
                    else -> it.textRange.parserIndex
                }
            }
            ?: tokens.lastOrNull()
                ?.parserIndex
            ?: textRange.parserIndex

    @Suppress("RedundantIf")
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CommandCall) return false

        if (type != other.type) return false
        if (command != other.command) return false
        if (!arguments.contentEquals(other.arguments)) return false
        if (tokenTextRange != other.tokenTextRange) return false
        if (inVariant != other.inVariant) return false
        if (textRange != other.textRange) return false
        if (parameterCount != other.parameterCount) return false

        return true
    }

    override fun hashCode(): Int {
        var result = type.hashCode()
        result = 31 * result + command.hashCode()
        result = 31 * result + arguments.contentHashCode()
        result = 31 * result + tokenTextRange.hashCode()
        result = 31 * result + inVariant.hashCode()
        result = 31 * result + textRange.hashCode()
        result = 31 * result + parameterCount
        return result
    }
}

@JsExport
data class EqualityStatement(
    /**
     * The entire range of this equality statement
     */
    override var textRange: RangeWithIndex,
    /**
     * The first/left side argument
     */
    @JsName("first")
    var first: Argument?,
    /**
     * The last/right side argument
     */
    @JsName("second")
    var second: Argument?,

    /**
     * The equality operator token
     */
    @JsName("eqToken")
    var eqToken: ParserItem.EqOp?,

    override val containingCommand: CommandReference?,

    override val parameter: ICaosParameter,

    internal val getTextActual: () -> String,
) : Argument {
    override val type: Int
        get() = ValueType.CONDITION.value

    override val text by lazy {
        getTextActual()
    }
    override val inEqualityExpression: Boolean
        get() = true

    override val parserItem: ParserItem<*>?
        get() = first?.parserItem
            ?: eqToken
            ?: second?.parserItem

    internal val arguments: List<Argument> by lazy {
        listOfNotNull(first, eqToken, second)
    }
    override val parserIndexStart: Int?
        get() = first?.parserIndexStart ?: eqToken?.parserIndexStart ?: second?.parserIndexStart

    override val parserIndexEnd: Int?
        get() = second?.parserIndexEnd ?: eqToken?.parserIndexEnd ?: eqToken?.parserIndexStart

    init {
        eqToken?.containingCommand = containingCommand
    }
}

