    command = EQ_COMMAND_TOKEN,
    parameters = conditionParameters.toTypedArray(),
    returnTypeId = ValueType.CONDITION.value,
    isRvalue = true,
    isLvalue = false,
    returnTypeName = "true|false",
    isCommand = false,
    variants = arrayOf("C1", "C2", "CV", "C3", "DS", "SM"),
    description = null,
    commandGroup = "Flow",
)

private fun condition(
    containingCommand: CommandReference?,
    parameter: ICaosParameter,
    textRange: RangeWithIndex,
): CommandCall {
    val range = RangeWithIndexImpl(
        startIndex = textRange.endIndex,
        endIndex = textRange.endIndex,
        start = textRange.end,
        end = textRange.end,
        parserIndex = textRange.parserIndex
    )
    return CommandCall(
        ValueType.CONDITION.value,
        command = ConditionCommand,
        tokenTextRange = range,
        inVariant = true,
        textRange = range,
        inEqualityExpression = true,
        arguments = emptyArray(),
        parameter = parameter,
        containingCommand = containingCommand,
        tokens = listOfNotNull(
            ParserItem.CommandToken(
                textRange,
                EQ_COMMAND_TOKEN
            )
        ).toTypedArray(),
        callType = CommandType.RVALUE
    )
}

private typealias ClosestByVariant = (commands: List<CaosCommand>) -> CaosCommand?


private val getClosestByVariantFilter: (variant: String) -> ClosestByVariant = { variant: String ->
    when (variant) {
        "C1" -> closestToC1
        "C2" -> closestToC2
        "CV" -> closestToCV
        "C3" -> closestToC3
        "DS" -> closestToDS
        "SM" -> closestToSM
        else -> throw Exception("Invalid variant found for get ClosestByVariant")
    }
}

private val closestToC1: ClosestByVariant = closest@{ commands: List<CaosCommand> ->
    when (commands.size) {
        0 -> null
        1 -> commands[0]
        else -> commands.firstOrNull {
            it.variants.indexOf("C2") >= 0
        } ?: commands.firstOrNull {
            it.variants.indexOf("C3") >= 0
        } ?: commands.firstOrNull {
            it.variants.indexOf("DS") >= 0
        } ?: commands.firstOrNull()
    }
}

