internal fun stitch(vararg items: TextWithRange): String {
    val itemsSorted = items.sortedBy { (it.textRange.start.line shl 8) or it.textRange.start.line }
    var last: TextWithRange? = null
    var out = ""
    for (item in itemsSorted) {
        if (item.text.startsWith('{')) {
            last = item
            continue
        }
        out += if (last != null) gap(last, item) else ""
        out += item.text
        last = item
    }
    return out
}

private fun gap(last: TextWithRange, next: TextWithRange): String {
    val lines = next.textRange.start.line - last.textRange.end.line
    val spaces = if (lines == 0) {
        next.textRange.start.character - last.textRange.end.character
    } else {
        next.textRange.start.character
    }
    val padding = next.textRange.startIndex - (lines + spaces + last.textRange.endIndex)
//    if (lines < 2 && padding > 0) {
//        Log.e(
//            "CommandWalker",
//            "Cannot calculate gap between elements. There is a space discrepancy of $padding characters"
//        )
//    }
    val out = if (padding > 0 && lines > 1) {
        "\n" + " ".repeat(padding) + "\n".repeat(lines - 1)
    } else {
        "\n".repeat(lines)
    }
    return out + " ".repeat(max(0, spaces - 1))
}

