@file:Suppress("unused")

package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosUniversalParser
import com.bedalton.creatures.caos.antlr.CaosUniversalParserBaseListener
import com.bedalton.creatures.caos.utils.token
import org.antlr.v4.kotlinruntime.Token

/**
 * Finds block ranges for scripts in file
 */
class ScriptOffsetsWalker : CaosUniversalParserBaseListener() {
    private val mScriptOffsets: MutableList<BlockRange> = mutableListOf()
    val scriptOffsets: Array<BlockRange> get() = mScriptOffsets.toTypedArray()
    private var start: Token? = null
    private var startCommand: String? = null
    private var isDDe: Boolean = false
    private val dde = token("dde:")

    override fun enterScriptStart(ctx: CaosUniversalParser.ScriptStartContext) {
        super.enterScriptStart(ctx)
        if (isDDe) {
            isDDe = false
            return
        }

        val start = start
        val newStart = ctx.start!!
        if (start != null && start.startIndex != ctx.start!!.startIndex) {
            mScriptOffsets.add(
                BlockRange(
                    startToken = startCommand,
                    endToken = null,
                    start = start,
                    end = newStart,
                    null,
                    depth = 0
                )
            )
        }
        this.start = newStart
        this.startCommand = ctx.text
    }
    override fun enterScriptEnd(ctx: CaosUniversalParser.ScriptEndContext) {
        super.enterScriptEnd(ctx)

        val start = start
            ?: return
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand,
                endToken = ctx.text,
                start = start,
                end = ctx.stop!!,
                null,
                depth = 0
            )
        )
        startCommand = null
        this.start = null
    }

    override fun enterWord(ctx: CaosUniversalParser.WordContext) {
        super.enterWord(ctx)
        isDDe = token(ctx.text) == dde
    }

    override fun enterElement(ctx: CaosUniversalParser.ElementContext) {
        super.enterElement(ctx)
        if (start != null) {
            return
        }
        if (ctx.findComment() != null) {
            return
        }
        start = ctx.start
        startCommand = null
    }

    override fun enterEof(ctx: CaosUniversalParser.EofContext) {
        super.enterEof(ctx)

        val start = start
            ?: return
        val end = ctx.start!!
        mScriptOffsets.add(
            BlockRange(
                startToken = startCommand,
                endToken = null,
                start = start,
                end = end,
                null,
                depth = 0
            )
        )
    }
    companion object {
        private const val TAG = "OffsetWalker"
    }
}