package com.bedalton.creatures.caos.collectors

import com.bedalton.creatures.caos.antlr.CaosUniversalParser
import com.bedalton.creatures.caos.antlr.CaosUniversalParserBaseListener
import com.bedalton.creatures.caos.collectors.ParserItem.IndexedVar
import com.bedalton.creatures.caos.libs.ErrorTypes
import com.bedalton.creatures.caos.server.PositionImpl
import com.bedalton.creatures.caos.server.RangeWithIndex
import com.bedalton.creatures.caos.server.RangeWithIndexImpl
import com.bedalton.creatures.caos.utils.Log
import com.bedalton.creatures.caos.utils.binaryToInteger
import com.bedalton.creatures.caos.utils.stripSurroundingQuotes
import com.bedalton.creatures.caos.utils.substringFromEnd
import com.strumenta.kotlinmultiplatform.BitSet
import org.antlr.v4.kotlinruntime.*
import org.antlr.v4.kotlinruntime.atn.ATNConfigSet
import org.antlr.v4.kotlinruntime.dfa.DFA
import org.antlr.v4.kotlinruntime.misc.Interval

@Suppress("unused")
internal class RawTokenizer(
    private val offsetIndex: Int? = null,
    private val offsetLine: Int? = null,
    private val offsetColumn: Int? = null,
    val checkCancelled: () -> Unit,
) : CaosUniversalParserBaseListener(), ANTLRErrorListener {

    val scriptRanges: Array<BlockRange> get() = mScriptRange.toTypedArray()
    val items: Array<ParserItem<*>> get() = mItems.toTypedArray()
    val variables: Array<IndexedVar> get() = mVariables.toTypedArray()
    val caos2Comments get() = mCao2Comments.toTypedArray()

    private val mScriptRange: MutableList<BlockRange> = mutableListOf()
    private var mScriptStart: Pair<RangeWithIndex, String>? = null
    private val mItems: MutableList<ParserItem<*>> = mutableListOf()
    private val mVariables: MutableList<IndexedVar> = mutableListOf()
    private val mCao2Comments = mutableListOf<ParserItem.Caos2Comment>()

    private val toRange: (start: Token, end: Token) -> RangeWithIndex by lazy {
        if (offsetIndex != null) {
            { start: Token, end: Token ->
                RangeWithIndexImpl(start, end, mItems.size, offsetIndex, offsetLine ?: 0, offsetColumn ?: 0)
            }
        } else {
            { start: Token, end: Token ->
                RangeWithIndexImpl(start, end, mItems.size)
            }
        }
    }

    override fun exitEveryRule(ctx: ParserRuleContext) {
        super.exitEveryRule(ctx)
        checkCancelled()
    }

    override fun enterElement(ctx: CaosUniversalParser.ElementContext) {
        super.enterElement(ctx)
        if (mScriptStart == null) {
            mScriptStart = Pair(toRange(ctx.start!!, ctx.start!!), "")
        }
    }

    override fun enterByteString(ctx: CaosUniversalParser.ByteStringContext) {
        super.enterByteString(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = ParserItem.ByteStringVal(
            textRange = range,
            value = ctx.text
        )
        mItems.add(token)
    }

    override fun enterWord(ctx: CaosUniversalParser.WordContext) {
        super.enterWord(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = ParserItem.CommandToken(
            range,
            ctx.text
        )
        mItems.add(token)
    }

    override fun enterControlStatementEnd(ctx: CaosUniversalParser.ControlStatementEndContext) {
        super.enterControlStatementEnd(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = ParserItem.CommandToken(
            range,
            ctx.text
        )
        mItems.add(token)
    }

    override fun enterControlStatementStart(ctx: CaosUniversalParser.ControlStatementStartContext) {
        super.enterControlStatementStart(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = ParserItem.CommandToken(
            range,
            ctx.text
        )
        mItems.add(token)
    }

    override fun enterWordPlus(ctx: CaosUniversalParser.WordPlusContext) {
        super.enterWordPlus(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = ParserItem.TokenVal(
            range,
            ctx.text
        )
        mItems.add(token)
    }

    override fun enterIncomplete(ctx: CaosUniversalParser.IncompleteContext) {
        val range = toRange(ctx.start!!, ctx.stop!!)
        val token = if (ctx.text.length == 3 && mItems.size > 1 && mItems.last().value?.toString()
                ?.uppercase() == "PICT" && mItems.getOrNull(mItems.lastIndex - 1).toString().uppercase() == "DDE:"
        ) {
            ParserItem.DdePictVal(
                range,
                Pair(ctx.text.first().code, ctx.text.last().code),
                ctx.text
            )
        } else {
            ParserItem.TokenVal(
                range,
                ctx.text,
            )
        }

        mItems.add(token)
    }

    override fun enterNumber(ctx: CaosUniversalParser.NumberContext) {
        super.enterNumber(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val item = when {
            ctx.BINARY_INT() != null -> ParserItem.BinaryVal(range, binaryToInteger(ctx.text), ctx.text)
            ctx.CHAR() != null -> ParserItem.CharVal(
                range,
                ctx.text.toCharArray().dropLast(1).lastOrNull()?.code ?: 0,
                ctx.text
            )
            ctx.FLOAT() != null -> ParserItem.FloatVal(range, ctx.text)
            ctx.INT() != null -> ParserItem.IntVal(range, ctx.text.toInt())
            else -> {
                Log.e(TAG, "Unhandled number context: '${ctx.text}'")
                return
            }
        }
        mItems.add(item)
    }

    override fun enterEqJoin(ctx: CaosUniversalParser.EqJoinContext) {
        super.enterEqJoin(ctx)
        val token = ParserItem.EqJoin(
            textRange = toRange(ctx.start!!, ctx.stop!!),
            value = ctx.text
        )
        mItems.add(token)
    }

    override fun enterEqOp(ctx: CaosUniversalParser.EqOpContext) {
        super.enterEqOp(ctx)
        val token = ParserItem.EqOp(
            textRange = toRange(ctx.start!!, ctx.stop!!),
            value = ctx.text
        )
        mItems.add(token)
    }

    override fun enterCaos2Tag(ctx: CaosUniversalParser.Caos2TagContext) {
        super.enterCaos2Tag(ctx)
        val start = ctx.CAOS2_START()?.symbol
            ?: return
        val wordContext = ctx.findCaos2TagName()
            ?: return

        val eq = ctx.CAOS2_EQUALS()?.symbol
            ?: return

        val token = ParserItem.TokenVal(
            wordContext.textRangeWithParserIndex(mItems.size),
            wordContext.trueText.stripSurroundingQuotes()
        )
        val parserItem = ParserItem.Caos2Comment(
            textRange = ctx.textRangeWithParserIndex(mItems.size),
            text = ctx.trueText.trim(),
            token = token,
            values = caos2Values(ctx),
            eq = ParserItem.TokenVal(
                textRange = eq.textRangeWithParserIndex(mItems.size),
                value = "="
            ),
            caos2Hash = ParserItem.TokenVal(
                textRange = start.textRangeWithParserIndex(mItems.size),
                value = "*#"
            ),
        )
        mCao2Comments.add(parserItem)
        mItems.add(parserItem)
    }

    override fun enterCaos2Comand(ctx: CaosUniversalParser.Caos2ComandContext) {
        super.enterCaos2Comand(ctx)
        val start = ctx.CAOS2_START()?.symbol
            ?: return
        val wordContext = ctx.findCaos2Word()
            ?: return
        val token = ParserItem.TokenVal(
            wordContext.textRangeWithParserIndex(mItems.size),
            wordContext.trueText.stripSurroundingQuotes()
        )
        val parserItem = ParserItem.Caos2Comment(
            textRange = ctx.textRangeWithParserIndex(mItems.size),
            text = ctx.trueText.trim(),
            token = token,
            values = caos2Values(ctx),
            eq = null,
            caos2Hash = ParserItem.TokenVal(
                textRange = start.textRangeWithParserIndex(mItems.size),
                value = "*#"
            ),
        )
        mCao2Comments.add(parserItem)
        mItems.add(parserItem)
    }

    private fun caos2Values(ctx: ParserRuleContext): Array<ParserItem<*>> {
        val intRegex = "[-+]?\\d+".toRegex()
        return ctx.children
            .orEmpty()
            .filterIsInstance<CaosUniversalParser.Caos2ValueContext>()
            .map {
                val text = it.trueText
                val range = it.textRangeWithParserIndex(mItems.size)
                if (intRegex.matches(text)) {
                    ParserItem.IntVal(
                        range,
                        text.toInt()
                    )
                } else if (text.startsWith('"') && text.endsWith('"')) {
                    ParserItem.C2eStringVal(
                        range,
                        text.stripSurroundingQuotes()
                    )
                } else {
                    ParserItem.TokenVal(
                        range,
                        text.stripSurroundingQuotes()
                    )
                }
            }
            .toTypedArray()
    }

    override fun enterComment(ctx: CaosUniversalParser.CommentContext) {
        super.enterComment(ctx)
        val token = ParserItem.Comment(
            textRange = toRange(ctx.start!!, ctx.stop!!),
            value = ctx.text
        )
        mItems.add(token)
    }

    override fun enterString(ctx: CaosUniversalParser.StringContext) {
        super.enterString(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val rawText = ctx.trueText
        val stringValue = if (rawText.length > 2) {
            rawText.substringFromEnd(1, 1)
        } else {
            ""
        }
        val token = ctx.C1_STRING()?.let {
            ParserItem.C1eStringVal(
                range,
                value = stringValue
            )
        } ?: ParserItem.C2eStringVal(
            range,
            value = stringValue
        )
        mItems.add(token)
    }

    override fun enterNumberedVar(ctx: CaosUniversalParser.NumberedVarContext) {
        super.enterNumberedVar(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        val textLength = if (ctx.OBVx() != null || ctx.VARx() != null)
            3
        else
            2
        val type = ctx.text.substring(0, textLength).uppercase().padEnd(4, 'x')
        val index = ctx.text.substring(textLength).toInt()
        val token = IndexedVar(
            textRange = range,
            value = ctx.text,
            type = type,
            index = index,
        )
        mVariables.add(token)
        mItems.add(token)
    }

    override fun enterScriptStart(ctx: CaosUniversalParser.ScriptStartContext) {
        super.enterScriptStart(ctx)
        val lastScriptStart = mScriptStart
        if (lastScriptStart != null && lastScriptStart.first.startIndex != ctx.start!!.startIndex) {
            mScriptRange.add(
                BlockRange(
                    startToken = lastScriptStart.second,
                    endToken = "",
                    startIndex = lastScriptStart.first.startIndex + (offsetIndex ?: 0),
                    endIndex = ctx.start!!.startIndex + (offsetIndex ?: 0),
                    start = PositionImpl(
                        line = lastScriptStart.first.start.line + (offsetLine ?: 0),
                        character = lastScriptStart.first.start.character + (if (lastScriptStart.first.start.line == 0) (offsetColumn
                            ?: 0) else 0)
                    ),
                    end = PositionImpl(
                        line = (ctx.start!!.line - 1) + (offsetLine ?: 0),
                        character = ctx.start!!.charPositionInLine + (if (ctx.start!!.line == 0) (offsetColumn
                            ?: 0) else 0)
                    ),
                    items.size,
                    depth = 0
                )
            )
        }
        val range = toRange(ctx.start!!, ctx.stop!!)
        mScriptStart = Pair(toRange(ctx.start!!, ctx.stop!!), ctx.text)
        mItems.add(ParserItem.CommandToken(range, ctx.text))
    }

    override fun enterScriptEnd(ctx: CaosUniversalParser.ScriptEndContext) {
        super.enterScriptEnd(ctx)
        val lastScriptStart = mScriptStart
            ?: Pair(toRange(ctx.start!!, ctx.start!!), "")
        mScriptStart = null
        val endToken = toRange(ctx.start!!, ctx.stop!!)
        mScriptRange.add(
            BlockRange(
                startToken = lastScriptStart.second,
                endToken = if (ctx.text.lowercase() == "endm") ctx.text else "",
                startIndex = lastScriptStart.first.startIndex + (offsetIndex ?: 0),
                endIndex = endToken.endIndex + (offsetIndex ?: 0),
                start = PositionImpl(
                    line = lastScriptStart.first.start.line + (offsetLine ?: 0),
                    character = lastScriptStart.first.start.character + (if (lastScriptStart.first.start.line == 0) (offsetColumn
                        ?: 0) else 0)
                ),
                end = PositionImpl(
                    line = endToken.end.line + (offsetLine ?: 0),
                    character = endToken.end.character + (if (endToken.end.line == 0) (offsetColumn ?: 0) else 0)
                ),
                items.size,
                depth = 0
            )
        )
        mItems.add(ParserItem.CommandToken(endToken, ctx.text))
    }


    override fun enterEof(ctx: CaosUniversalParser.EofContext) {
        super.enterEof(ctx)
        val lastScriptStart = mScriptStart
            ?: return
        mScriptStart = null
        val endToken = toRange(ctx.stop!!, ctx.stop!!)
        mScriptRange.add(
            BlockRange(
                startToken = lastScriptStart.second,
                endToken = "",
                startIndex = lastScriptStart.first.startIndex + (offsetIndex ?: 0),
                endIndex = endToken.endIndex + (offsetIndex ?: 0),
                start = PositionImpl(
                    line = lastScriptStart.first.start.line + (offsetLine ?: 0),
                    character = lastScriptStart.first.start.character + (if (lastScriptStart.first.start.line == 0) (offsetColumn
                        ?: 0) else 0)
                ),
                end = PositionImpl(
                    line = endToken.end.line + (offsetLine ?: 0),
                    character = endToken.end.character + (if (endToken.end.line == 0) (offsetColumn ?: 0) else 0),
                ),
                items.size,
                depth = 0
            )
        )
    }

    override fun enterAutocompleteItem(ctx: CaosUniversalParser.AutocompleteItemContext) {
        super.enterAutocompleteItem(ctx)
        val range = toRange(ctx.start!!, ctx.stop!!)
        mItems.add(
            ParserItem.AutocompleteHint(
                textRange = range,
                value = ctx.text
            )
        )
    }

    companion object {
        private const val TAG = "RawTokenizer"
    }

    override fun reportAmbiguity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        exact: Boolean,
        ambigAlts: BitSet,
        configs: ATNConfigSet,
    ) {

    }

    override fun reportAttemptingFullContext(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        conflictingAlts: BitSet,
        configs: ATNConfigSet,
    ) {
    }

    override fun reportContextSensitivity(
        recognizer: Parser,
        dfa: DFA,
        startIndex: Int,
        stopIndex: Int,
        prediction: Int,
        configs: ATNConfigSet,
    ) {
    }

    override fun syntaxError(
        recognizer: Recognizer<*, *>,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String,
        e: RecognitionException?,
    ) {
        val ctx = offendingSymbol as? CommonToken
            ?: return
        val text = ctx.text
            ?: return
        val range = ctx.toRange(offsetIndex, offsetLine, offsetColumn)


        mItems.add(
            ParserItem.ErrorVal(
                range,
                "Invalid input '$text'",
                ErrorTypes.GENERAL,
                text
            )
        )
    }

}

internal fun ParserRuleContext.textRangeWithParserIndex(parserIndex: Int): RangeWithIndex {
        return RangeWithIndexImpl(
            this,
            parserIndex
        )
    }

internal fun ParserRuleContext.textRangeWithoutParserIndex(): RangeWithIndex {
    return RangeWithIndexImpl(
        this,
        null
    )
}

internal fun Token.textRangeWithParserIndex(parserIndex: Int): RangeWithIndex {
    val start = startPoint()
    val stop = endPoint()
    return RangeWithIndexImpl(
        startIndex = startIndex,
        endIndex = stopIndex,
        start = PositionImpl(
            line = start.line - 1,
            character = stop?.column ?: 0
        ),
        end = PositionImpl(
            line = stop?.line?.let { it - 1 } ?: 0,
            character = if (start.line == stop?.line) {
                maxOf(0, start.column + text!!.length)
            } else {
                stop?.column ?: 1
            } - 1
        ),
        parserIndex = parserIndex
    )
}


internal fun Token.textRangeWithoutParserIndex(): RangeWithIndex {
    val start = startPoint()
    val stop = endPoint()
    return RangeWithIndexImpl(
        startIndex = startIndex,
        endIndex = stopIndex,
        start = PositionImpl(
            line = start.line - 1,
            character = stop?.column ?: 0
        ),
        end = PositionImpl(
            line = stop?.line?.let { it - 1 } ?: 0,
            character = if (start.line == stop?.line) {
                maxOf(0, start.column + text!!.length)
            } else {
                stop?.column ?: 1
            } - 1
        ),
        parserIndex = null
    )
}
internal val ParserRuleContext.trueText: String
    get() {
        val a: Int = start!!.startIndex
        val b: Int = stop!!.stopIndex
        val interval = Interval(a, b)
        return start!!.inputStream!!.getText(interval)
    }