val VAR_REGEX = "^((va|ov|mv)\\d){2}|((obv|var)\\d)".toRegex(RegexOption.IGNORE_CASE)
//private const val TAG = "CURSOR"

@JsExport
fun getCursorPosition(
    parseResult: ParseResult,
    lineNumber: Int,
    column: Int,
    incomplete: Boolean,
): CursorDataImpl? {
    val commandCalls = parseResult.commandCalls
    if (commandCalls.isEmpty() && parseResult.equalityStatements.isEmpty()) {
        return null
    }
    // Filter calls to those enclosing position
    val inRangeCalls = commandCalls.filter { call: CommandCall ->
        inRange(call.textRange, lineNumber, column, ignoreColumn = false, soft = true)
    }

    // Find the closest call to cursor
    val closestResult = getClosestItem(inRangeCalls, lineNumber, column, !incomplete)
    var closest: CommandCall? = closestResult?.closest

    // Get all tokens on row
    val inRangeItems = parseResult.items.filter { inRange(it.textRange, lineNumber, column, true) }

    // Find the closest parser item
    val closestItemResult = getClosestItem(inRangeItems, lineNumber, column, true)
    val closestItem: ParserItem<*>? = closestItemResult?.closest


    var commandParametersTemp: Array<ICaosParameter>? = emptyArray()
    var missingParameters: List<ICaosParameter> = emptyList()
    var matchingEqualityStatements: List<EqualityStatement> = emptyList()
    var index = 0
    var inCommand = true
    var processCommand: (closestCall: CommandCall?) -> Unit = {}

    // Inline function to set the "closest*" variables
    // This is needed to support jumping out of complete commands to their enclosing commands
    processCommand = run@{ closestCall: CommandCall? ->
        // Get current command calls arguments
        val commandArguments: Array<Argument> = closestCall?.arguments ?: emptyArray()

        // Get argument at line and column for this command
        var argumentIndex = commandArguments.indexOfFirst argumentIndex@{ a ->
            if (inRange(a.textRange, lineNumber, column, ignoreColumn = false, soft = false)) {
                if (column <= a.textRange.end.character) {
                    return@argumentIndex true
                }
            }
            false
        }

        // If no argument at cursor for this command
        if (argumentIndex < 0) {
            if (commandArguments.isNotEmpty()) {
                // Get argument before the cursor
                argumentIndex = commandArguments.indexOfFirst { a -> column > a.textRange.end.character }
                if (argumentIndex < 0) {
                    // Still no argument, just get next argument index
                    commandArguments.size
                } else if (commandArguments.isNotEmpty() && commandArguments.getOrNull(argumentIndex)?.type != ValueType.TOKEN.value && commandArguments.getOrNull(
                        argumentIndex
                    )?.type != ValueType.UNKNOWN.value
                ) {
                    argumentIndex += 1
                }
            } else {
                argumentIndex = 0
            }
        }

        // Determine whether we are still in a command
        if (closestItem != null && commandArguments.getOrNull(argumentIndex) != null && closestItem.textRange.endIndex > (commandArguments.getOrNull(
                argumentIndex
            )?.textRange?.endIndex ?: 0)
        ) {
            inCommand = false
        }


        // Offset the index to find the one currently being edited
        val indexMod = if (argumentIndex == 0) 1 else 0
        commandParametersTemp = closestCall?.command?.parameters

        // Establish if parameters could indeed be missing
        // This has to do with variables not registering as commands,
        // but still completing commands
        val argumentType = closestItem?.actualType
        val isIncompleteToken = argumentType == ValueType.TOKEN.value ||
                argumentType == ValueType.UNKNOWN.value
        val isCompletable = !isIncompleteToken &&
                argumentType != ValueType.VARIABLE.value
        val noMissing = commandArguments.isNotEmpty() &&
                commandArguments.size - 1 >= commandParametersTemp?.lastIndex.orElse(argumentIndex) &&
                isCompletable

        // Get the missing parameters if any
        var missing: List<ICaosParameter> = if (noMissing) {
            emptyList()
        } else {
            commandParametersTemp?.let {
                val missingParameterStart = max(min(argumentIndex, commandArguments.size - indexMod), 0)
                if (it.isNotEmpty() && missingParameterStart >= 0) {
                    it.slice(missingParameterStart until it.size)
                } else {
                    emptyList()
                }
            } ?: emptyList()
        }

        val isEqLike =
            (closestItem?.actualType == ValueType.EQ_OP.value || closestItem?.actualType == ValueType.EQ_JOIN.value)
        val inEq = closestCall?.inEqualityExpression ?: false

        // If no missing arguments, possibly jump out to enclosing command
        if (missing.isEmpty()) {
            var jumpOut = true
            if (inRange(closestItem?.textRange, lineNumber, column)) {
                if (closestItem != null && !isComplete(closestItem, lineNumber, column)) {
                    jumpOut = false
                }
            }
            if (!inEq && isEqLike) {
                jumpOut = false
            }
            jumpOut = jumpOut || !inCommand
            if (jumpOut) {
                val commandCallIndex = closestCall?.containingCommand?.commandCallIndex
                if (commandCallIndex != null) {
                    processCommand(parseResult.commandCalls[commandCallIndex])
                } else {
                    inCommand = false
                    closest = null
                    missingParameters = emptyList()
                }
                return@run
            } // end jump out
        } // end no missing

        // Find index of arguments
        matchingEqualityStatements = parseResult
            .equalityStatements
            .filter { eq ->
                inRange(eq.textRange, lineNumber, column, ignoreColumn = true, soft = true)
            }

        index = if (argumentIndex >= 0) argumentIndex else 0

        // If cursor is at end of command call
        inCommand = inCommand && closestItem != null && closestCall
            ?.arguments
            ?.indexOfFirst { arg ->
                val start = arg.textRange.start
                inRange(arg.textRange, start.line, start.character + 1)
            }.orElse(-1) >= 0
        if (!inCommand && !(inEq && isEqLike)) {
            val commandCallIndex = closestCall?.containingCommand?.commandCallIndex
            if (commandCallIndex != null) {
                processCommand(parseResult.commandCalls[commandCallIndex])
                return@run
            } else {
                closest = null
                missing = emptyList()
            }
        }
        closest = closestCall
        missingParameters = missing
    } // End Process command

    if (closest != null) {
        processCommand(closest)
    }

    val commandParameters = commandParametersTemp

    // Check need for a parameter
    val hasMissingParameters = missingParameters.isNotEmpty()
    val isNotCompleteOrAtColumn = closestItem != null &&
            (closestItem.textRange.end.character == column || !isComplete(closestItem, lineNumber, column))
    val needsParameter = (hasMissingParameters || isNotCompleteOrAtColumn)

    // Check if expecting and has a parameter
    val hasClosestParameter = needsParameter &&
            inCommand &&
            !commandParameters.isNullOrEmpty() &&
            commandParameters.size > index

    // Find the closest parameter based on argument index
    val closestParameter = if (hasClosestParameter) commandParameters!![index] else null

    val closestItemText = closestItem?.text?.lowercase()
    val closestCommandString = closest?.command?.command?.lowercase() ?: ""
    val beforeTextIsMatchingCommand = closestItemText != null &&
            (VAR_REGEX.matches(closestItemText) || closestCommandString.endsWith(closestItemText))

    // Get value list if any for an equality statement value
    val equalityValuesList: CaosValuesList? = getEqualityValuesList(
        parseResult,
        closestItem,
        lineNumber,
        column
    )

    return CursorDataImpl(
        command = closest?.command,
        missing = missingParameters.toTypedArray(),
        closestParameter = closestParameter,
        beforeText = if (!beforeTextIsMatchingCommand) closestItem?.text else "",
        previousTokens = dismissTokensIfUsed(closest?.command, closestItemResult?.previous ?: emptyArray()),
        closestItem = closestItem,
        line = lineNumber,
        character = column,
        eqValuesList = equalityValuesList,
        inEqualityStatement = matchingEqualityStatements.isNotEmpty()
    )
}


/**
 * Discard tokens in a list of tokens that where used by a command call
 * Sometimes a token array is given, but the last two tokens were actually used in the command call,
 * this returns that array minus the two tokens used
 * @param currentCommand
 * @param tokens
 */
fun dismissTokensIfUsed(
    currentCommand: ICaosCommand?,
    tokens: Array<CommandToken>,
): Array<CommandToken> {
    if (currentCommand == null) {
        return tokens
    }
    var tokensTemp = tokens.copyOf().map { t ->
        token(t.text.lowercase())
    }
    val commandTokens: List<Int> = currentCommand.command.lowercase()
        .split(' ')
        .map { c: String ->
            token(c)
        }
    val startIndex = tokensTemp.indexOf(commandTokens[0])
    if (startIndex < 0) {
        return tokens
    }

    val availableTokens = min(commandTokens.size, tokensTemp.size - startIndex)
    tokensTemp = tokensTemp.drop(startIndex)
    var i = 0
    while (i < availableTokens) {
        if (tokensTemp[i] != commandTokens[i]) {
            return tokens.drop(i).toTypedArray()
        }
        i++
    }
    if (i == tokens.size - 1) {
        return emptyArray()
    }
    return tokens.drop(i + 1).toTypedArray()
}

/**
 * Object of an item and its distance to a line and column
 */
private data class Distanced<T : HasRange>(
    val item: T,
    val distance: Distance,
)

/**
 * Distance between two positions
 */
private data class Distance(
    val lineOffset: Int,
    val columnOffset: Int,
)


/**
 * Gets an items distance from a given line and column
 * @param range
 * @param lineNumber
 * @param column
 */
private fun getDistance(range: RangeWithIndex, lineNumber: Int, column: Int): Distance {
    return Distance(
        lineOffset = lineNumber - range.start.line,
        columnOffset = if (lineNumber == range.start.line) {
            (column - range.start.character)
        } else {
            range.start.character
        }
    )
}


@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
data class ClosestItemResult<T : HasRange>(
    @JsName("closest")
    val closest: T,
    @JsName("previous")
    val previous: Array<CommandToken>,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is ClosestItemResult<*>) return false

        if (closest != other.closest) return false
        if (!previous.contentEquals(other.previous)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = closest.hashCode()
        result = 31 * result + previous.contentHashCode()
        return result
    }
}


/**
 * Gets the closest item to a given line and column
 * If notAfter is set, it will only get the closest item without going past the column and line
 * @param inRangeItems
 * @param lineNumber
 * @param column
 * @param notAfter
 */
@Suppress("NON_EXPORTABLE_TYPE")
@JsExport
fun <T : HasRange> getClosestItem(
    inRangeItems: Array<T>,
    lineNumber: Int,
    column: Int,
    notAfter: Boolean,
): ClosestItemResult<T>? {
    return getClosestItem(
        inRangeItems.toList(),
        lineNumber,
        column,
        notAfter
    )
}

internal fun <T : HasRange> getClosestItem(
    inRangeItemsIn: List<T>,
    lineNumber: Int,
    column: Int,
    notAfter: Boolean,
): ClosestItemResult<T>? {

    var inRangeItems = inRangeItemsIn
    if (inRangeItems.isEmpty()) {
        return null
    }

    if (notAfter) {
        inRangeItems = inRangeItems.filter { item ->
            item.textRange.start.line == lineNumber && item.textRange.start.character <= column
        }
    }
    if (inRangeItems.isEmpty()) {
        return null
    }
    // Combine call with distance to lineNumber/Column
    val distanced: List<Distanced<T>> = inRangeItems
        .map { call ->
            Distanced(item = call, distance = getDistance(call.textRange, lineNumber, column))
        }

    // Find all commands on same line
    val sameLine: List<Distanced<T>> = distanced
        .filter { c -> c.distance.lineOffset == 0 }
        .sortedWith { a: Distanced<T>, b: Distanced<T> ->
            a.distance.columnOffset - b.distance.columnOffset
        }

    if (sameLine.isNotEmpty()) {
        // Sort by column distance, and return nearest
        var index: Int? = null


        for (i in sameLine.indices) {
            val item = sameLine[i]
            if (item.item.textRange.start.character < column) {
                index = i
                break
            }
        }
        if (index == null) {
            return null
        }
        val maxItems = 5
        val items = if (sameLine.size > maxItems) {
            sameLine.drop(0).slice(0..4)
        } else {
            sameLine.drop(0)
        }
        val tokens: MutableList<CommandToken> = mutableListOf()
        var stillTokens = true
        for (temp in items) {
            val item = temp.item
            if (item !is CommandToken) {
                stillTokens = (item is ParserItem.TokenVal)
            } else if (stillTokens) {
                tokens.add(item)
            }
        }

        return ClosestItemResult(
            closest = sameLine[0].item,
            previous = tokens.reversed().toTypedArray()
        )
    }

    // Sort distanced by
    distanced.sortedWith { a, b ->
        ((a.distance.lineOffset shl 16) or a.distance.columnOffset) - ((b.distance.lineOffset shl 16) or b.distance.columnOffset)
    }

    // Find the closest call in distanced
    var min: Distanced<T> = distanced[0]
    // Search all distanced
    for (call in distanced) {
        // Distanced is sorted by line Int
        // So a change in line means it is guaranteed to be further away
        if (call.distance.lineOffset > min.distance.lineOffset) {
            break
        }
        // Grab closest
        if (call.distance.columnOffset < min.distance.columnOffset) {
            min = call
        }
    }
    // Return the closest call
    return ClosestItemResult(
        closest = min.item,
        previous = emptyArray()
    )
}

/**
 * Get values list for equality statement based on opposing command
 * @param parseResult
 * @param lineNumber
 * @param column
 */
fun getEqualityValuesList(
    parseResult: ParseResult,
    closestItem: ParserItem<*>?,
    lineNumber: Int,
    column: Int,
): CaosValuesList? {

    val closetItemContainsCursor = closestItem != null &&
            inRange(closestItem.textRange, lineNumber, column, ignoreColumn = false, soft = true)
    val parserIndexBeforeClosestItem = closestItem?.parserIndex?.let { it - 1 }
    val equalityStatement = parseResult.equalityStatements
        .filter { eq ->
            if (eq.arguments.isEmpty()) {
                return@filter false
            }
            val lastArgumentParserIndex = eq.arguments.lastOrNull()?.parserIndex
            (closetItemContainsCursor && lastArgumentParserIndex == parserIndexBeforeClosestItem) ||
                    inRange(eq.textRange, lineNumber, column, ignoreColumn = false, soft = true)
        }
        .maxByOrNull { a -> a.startIndex }
        ?: return null

    val cursorInFirstArgument = inRange(equalityStatement.first?.textRange, lineNumber, column)

    val shouldComplete: Boolean
    var other: Argument? = null

    // Assign other command and should complete flag
    if (cursorInFirstArgument && equalityStatement.second is CommandCall) {
        shouldComplete = shouldCompleteEqualityWith(equalityStatement.first?.parserItem)
        other = equalityStatement.second
    } else if (!cursorInFirstArgument && equalityStatement.first is CommandCall) {
        shouldComplete = shouldCompleteEqualityWith(equalityStatement.second?.parserItem)
        other = equalityStatement.first
    } else {
        shouldComplete = false
    }
    if (!shouldComplete || other !is CommandCall) {
        return null
    }
    val variant = parseResult.variant
    val valuesListIds: VariantData<Int>? = other.command.returnValuesListIds
    val valuesListId = valuesListIds?.get(variant)
        ?: return null
    return getValuesList(valuesListId)
}


private fun shouldCompleteEqualityWith(item: ParserItem<*>?): Boolean {
    return when (item?.actualType) {
        ValueType.COMMAND.value -> true
        ValueType.TOKEN.value -> true
        ValueType.UNKNOWN.value -> true
        ValueType.PLACEHOLDER.value -> true
        null -> true
        else -> false
    }
}

/**
 * Gets a cursor position using un-parsed CAOS text
 * @param variant
 * @param text
 * @param lineNumber
 * @param column
 * @param parseOnlyNear
 * @param incomplete
 * @param keepGoing
 */
@JsExport
// noinspection JSUnusedGlobalSymbols
fun getCursorPositionFromRawText(
    variant: GameVariant,
    text: String,
    lineNumber: Int,
    column: Int,
    parseOnlyNear: Boolean? = null,
    incomplete: Boolean? = null,
    keepGoing: (() -> Boolean)? = null,
): CursorDataImpl? {

    val result = try {
        if (parseOnlyNear != false) {
            parseCaosNear(variant, text, lineNumber, column, keepGoing = keepGoing)
        } else {
            parseCaos(variant, text, keepGoing)//parseCaosNear(variant, text, lineNumber + 1, column + 1);
        }
    } catch (e: Exception) {
        return null
    }

    return getCursorPosition(result, lineNumber, column, incomplete != false)
}

/**
 * Checks if an item should actually be completed
 */
@JsExport
fun cancelComplete(closestItem: ParserItem<*>, line: Int, character: Int): Boolean {
    if (!inRange(closestItem.textRange, line, character, ignoreColumn = false, soft = false)) {
        return false
    }
    return when (closestItem.actualType) {
        ValueType.TOKEN.value,
        ValueType.COMMAND.value,
        ValueType.UNKNOWN.value,
        ValueType.STRING.value,
        -> {
            false
        }

        ValueType.CAOS2_COMMENT.value -> {
            closestItem.textRange.start.character + 2 > character
        }

        else -> {
            true
        }
    }
}

/**
 * Checks if a given cursor is inside a matching pair of quotes.
 * Used to prevent completions in strings
 */
@JsExport
fun inQuotes(closestItem: ParserItem<*>, line: Int, character: Int): Boolean {
    if (!closestItem.text.startsWith('"')) {
        return false
    }
    val start = closestItem.textRange.start
    val end = closestItem.textRange.end
    if (start.line == line) {
        return if (end.line != line) {
            true
        } else {
            (start.character < character && character <= end.character)
        }
    } else if (start.line < line) {
        return if (end.line > line) {
            true
        } else {
            val endQuote = if (closestItem.text.endsWith('"')) 1 else 0
            (character < end.character - endQuote)
        }
    } else if (start.line > line) {
        return false
    } else {
        return false
    }
}


/**
 * Check if a parser item is complete as it is
 * Closed items are completely quoted string, numbers and word 4-letter tokens
 */
private fun isComplete(parserItem: ParserItem<*>, line: Int, character: Int): Boolean {
    if (inQuotes(parserItem, line, character)) {
        return false
    }
    val text = parserItem.text
    // If is numeric
    if ("((\\d+)?\\.\\d+)|(\\d+)".toRegex().matches(text)) {
        return false
    }
    if (parserItem.actualType == ValueType.TOKEN.value) {
        return false
    }

    return text.startsWith('"') || text.length == 4

}