package com.bedalton.creatures.caos.formatter

import com.bedalton.creatures.caos.server.GameVariant
import com.bedalton.creatures.caos.utils.like
import com.bedalton.creatures.caos.utils.notLike
import kotlinx.serialization.SerialName
import kotlin.math.floor
import kotlin.math.max


/**
 * Copy of CAOS formatter options with only non-null values
 */
internal class CaosFormatterOptionsImpl(val variant: GameVariant, opts: CaosFormatterOptions?): CaosFormatterOptions {
    /**
     * Size of a tab in spaces.
     */
    override val tabSize: Int = opts?.tabSize ?: 4

    /**
     * Prefer spaces to tabs.
     */
    override val insertSpaces: Boolean = opts?.insertSpaces ?: true

    /**
     * Trim trailing whitespaces on a line.
     */
    override val trimTrailingWhitespace: Boolean = opts?.trimTrailingWhitespace ?: (variant like "C1")

    /**
     * Insert a newline character at the end of the file if one does not exist.
     */
    override val insertFinalNewline: Boolean = opts?.insertFinalNewline ?: false

    /**
     * Trim all newlines after the final newline at the end of the file.
     */
    override val trimFinalNewlines: Boolean = opts?.trimFinalNewlines ?: (variant like "C1" || variant like "C2")

    /**
     * Allow multiple commands to be on the same line
     */
    override val keepSameLine: Boolean = opts?.keepSameLine ?: (variant notLike "C1" && variant notLike "C2")


    /**
     * Whether to re-indent comments
     */
    override val indentComments: Boolean = opts?.indentComments ?: true

    /**
     * What kind of indent to add to a continuation
     */
    override val continuationIndent: Int = opts?.continuationIndent ?: max(1, floor(tabSize / 2.0).toInt())

    /**
     * Whether to add inner spaces between items in a byte-string
     * [ 1 2 3 ] or [1 2 3]
     */
    override val spaceBetweenByteStingBrackets: Boolean = opts?.spaceBetweenByteStingBrackets ?: false

    /**
     * The minimum number of new lines between two block level elements
     */
    override val minBlankLines: Int = max(0, opts?.minBlankLines ?: 0)

    /**
     * Maximum number of blank lines between comments, commands, scripts
     */
    override val maxBlankLines: Int by lazy {
        if ((opts?.maxBlankLines ?: -1) < 0) {
            Short.MAX_VALUE.toInt()
        } else {
            opts?.maxBlankLines ?: Short.MAX_VALUE.toInt()
        }
    }

    /**
     * The newline character or characters to use in the file
     */
    @SerialName("newlineChar")
    override val newLineChar: String = opts?.newLineChar ?: "\r\n"

    /**
     * Whether to enforce the minimum blank lines rule after a comment
     * If false, no blank lines are required after a comment
     */
    override val forceMinBlankLinesAfterComments: Boolean = opts?.forceMinBlankLinesAfterComments ?: false
}

/**
 * Customization options for the CAOS formatter
 */
expect interface CaosFormatterOptions {
    /**
     * Size of a tab in spaces.
     */
    val tabSize: Int

    /**
     * Prefer spaces to tabs.
     */
    val insertSpaces: Boolean

    /**
     * Trim trailing whitespaces on a line.
     */
    val trimTrailingWhitespace: Boolean?

    /**
     * Insert a newline character at the end of the file if one does not exist.
     */
    val insertFinalNewline: Boolean?

    /**
     * Trim all newlines after the final newline at the end of the file.
     */
    val trimFinalNewlines: Boolean?

    /**
     * Whether to allow multiple commands on the same line
     */
    val keepSameLine: Boolean?

    /**
     * The minimum number of newlines between block lines
     */
    val minBlankLines: Int?

    /**
     * The maximum number of blank lines between comments, commands, and scripts
     */
    val maxBlankLines: Int?

    /**
     * Whether to adjust indent on comments
     */
    val indentComments: Boolean?

    /**
     * What kind of indent to add to a continuation
     */
    val continuationIndent: Int?

    /**
     * Whether to insert spaces before and after brackets in a Byte or Animation string
     */
    val spaceBetweenByteStingBrackets: Boolean?

    /**
     * Newline char or chars to use
     */
    val newLineChar: String?

    /**
     * Whether to enforce the minimum-blank-lines after a comment
     * If false, it is possible to have no blank lines between a comment and the command that follows
     */
    val forceMinBlankLinesAfterComments: Boolean?
}

@Suppress("unused")
class CaosFormatterOptionsBuilder : CaosFormatterOptions {

    private var mTabSize: Int? = null

    /**
     * Size of a tab in spaces.
     */
    override val tabSize: Int
        get() = mTabSize ?: 4

    /**
     * Set size of a tab in spaces.
     */
    fun withTabSize(tabSize: Int?): CaosFormatterOptionsBuilder {
        mTabSize = tabSize
        return this
    }

    private var mInsertSpaces: Boolean? = null

    /**
     * Prefer spaces to tabs.
     */
    override val insertSpaces: Boolean
        get() = mInsertSpaces ?: true

    /**
     * Set prefer spaces to tabs.
     */
    fun withInsertSpaces(insert: Boolean?): CaosFormatterOptionsBuilder {
        mInsertSpaces = insert
        return this
    }

    private var mTrimTrailingWhitespace: Boolean? = null

    /**
     * Set trim trailing whitespaces on a line.
     */
    override val trimTrailingWhitespace: Boolean?
        get() = mTrimTrailingWhitespace

    /**
     * Set trim trailing whitespaces on a line.
     */
    fun withTrimTrailingWhitespace(trim: Boolean): CaosFormatterOptionsBuilder {
        mTrimTrailingWhitespace = trim
        return this
    }


    private var mInsertFinalNewline: Boolean? = null

    /**
     * Insert a newline character at the end of the file if one does not exist.
     */
    override val insertFinalNewline: Boolean?
        get() = mInsertFinalNewline


    /**
     * Insert a newline character at the end of the file if one does not exist.
     */
    fun withInsertFinalNewline(insert: Boolean?): CaosFormatterOptionsBuilder {
       mInsertFinalNewline = insert
        return this
    }

    /**
     * Trim all newlines after the final newline at the end of the file.
     */
    private var mTrimFinalNewlines: Boolean? = null

    override val trimFinalNewlines: Boolean? get() = mTrimFinalNewlines

    fun withTrimFinalNewlines(trim: Boolean?): CaosFormatterOptionsBuilder {
        mTrimFinalNewlines = trim
        return this
    }


    /**
     * Whether to allow multiple commands on the same line
     */
    private var mKeepSameLine: Boolean? = null

    override val keepSameLine: Boolean?
        get() = mKeepSameLine

    fun withKeepSameLine(keep: Boolean?): CaosFormatterOptionsBuilder {
        this.mKeepSameLine = keep
        return this
    }

    /**
     * The minimum number of newlines between block lines
     */
    private var mMinBlankLines: Int? = null

    override val minBlankLines: Int?
        get() = mMinBlankLines

    fun withMinBlankLines(minBlankLines: Int?): CaosFormatterOptionsBuilder {
        this.mMinBlankLines = minBlankLines
        return this
    }

    /**
     * The maximum number of blank lines between comments, commands, and scripts
     */
    private var mMaxBlankLines: Int? = null

    override val maxBlankLines: Int?
        get() = mMaxBlankLines

    fun withMaxBlankLines(maxBlankLines: Int?): CaosFormatterOptionsBuilder {
        mMaxBlankLines = maxBlankLines
        return this
    }

    private var mIndentComments: Boolean? = null

    /**
     * Whether to adjust indent on comments
     */
    override val indentComments: Boolean? get() = mIndentComments

    /**
     * Whether to adjust indent on comments
     */
    fun withIndentComments(indent: Boolean?): CaosFormatterOptionsBuilder {
        mIndentComments = indent
        return this
    }

    /**
     * What kind of indent to add to a continuation
     */
    private var mContinuationIndent: Int? = null

    override val continuationIndent: Int?
        get() = mContinuationIndent

    fun withContinuationIndent(indent: Int?): CaosFormatterOptionsBuilder {
        mContinuationIndent = indent
        return this
    }

    /**
     * Whether to insert spaces before and after brackets in a Byte or Animation string
     */
    private var mSpaceBetweenByteStingBrackets: Boolean? = null

    override val spaceBetweenByteStingBrackets: Boolean?
        get() = mSpaceBetweenByteStingBrackets

    fun withSpaceBetweenByteStringBrackets(addSpace: Boolean?): CaosFormatterOptionsBuilder {
        this.mSpaceBetweenByteStingBrackets = addSpace
        return this
    }

    /**
     * Newline char or chars to use
     */
    private var mNewLineChar: String? = null

    override val newLineChar: String?
        get() = mNewLineChar

    fun withNewlineChar(newline: String?): CaosFormatterOptionsBuilder {
        mNewLineChar = newline
        return this
    }

    /**
     * Whether to enforce the minimum-blank-lines after a comment
     * If false, it is possible to have no blank lines between a comment and the command that follows
     */
    private var mForceMinBlankLinesAfterComments: Boolean? = null

    override val forceMinBlankLinesAfterComments: Boolean?
        get() = mForceMinBlankLinesAfterComments

    fun withForceMinBlankLinesAfterComments(force: Boolean?): CaosFormatterOptionsBuilder {
        mForceMinBlankLinesAfterComments = force
        return this
    }

}