/**
 * Represents a single command in the CAOS language
 */
@Serializable
internal data class CaosCommand(
    val id: Int,
    val command: String,
    val parameters: Array<CaosParameter>,
    val returnTypeId: Int,
    val description: String? = null,
    val returnValuesListIds: Map<String, Int>? = null,
    val requiresOwnr: Int = 0,
    val variants: Array<String>,
    val rvalue: Boolean,
    val lvalue: Boolean,
    val lvalueName: String? = null,
    val commandGroup: String,
    val doifFormat: String? = null,
    val requiresCreatureOwnr: Boolean = false
) {

    val returnType: ValueType get() = ValueType.fromIntValue(returnTypeId)

    val tokens by lazy {
        command.split(' ').map { token(it) }.toIntArray()
    }

    val fullCommandHeader: String by lazy {
        val commandHeader = formatNameWithType(command, returnType)
        parameters.nullIfEmpty()?.let {
            val builder = StringBuilder(commandHeader)
            for (parameter in parameters) {
                builder.append(" ").append(formatNameWithType(parameter.name, parameter.type))
            }
            builder.toString()
        } ?: commandHeader
    }

    val isCommand: Boolean by lazy {
        !(rvalue || lvalue)
    }

    val returnValuesList: HasGetter<CaosVariant, CaosValuesList?> by lazy {
        HasGetterImpl get@{ key ->
            val valuesListId = returnValuesListIds?.get(key.code)
                ?: return@get null
            CaosLibs.valuesList[valuesListId]
        }
    }


    fun requiresOwnr(variant: CaosVariant): Boolean {
        return if (variant.isOld)
            requiresOwnr != 0
        else
            abs(requiresOwnr) == 2
    }

    fun requiresOwnrIsError(variant: CaosVariant): Boolean {
        return if (variant.isOld)
            requiresOwnr > 0
        else
            requiresOwnr == 2
    }

    fun requiresOwnrIsWarning(variant: CaosVariant): Boolean {
        return if (variant.isOld)
            requiresOwnr < 0
        else
            requiresOwnr == -2
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CaosCommand) return false

        if (id != other.id) return false
        if (command != other.command) return false
        if (!parameters.contentEquals(other.parameters)) return false
        if (returnType != other.returnType) return false
        if (description != other.description) return false
        if (returnValuesListIds != other.returnValuesListIds) return false
        if (requiresOwnr != other.requiresOwnr) return false
        if (variants != other.variants) return false
        if (rvalue != other.rvalue) return false
        if (lvalue != other.lvalue) return false
        if (lvalueName != other.lvalueName) return false
        if (commandGroup != other.commandGroup) return false
        if (doifFormat != other.doifFormat) return false
        if (requiresCreatureOwnr != other.requiresCreatureOwnr) return false

        return true
    }

    override fun hashCode(): Int {
        var result = id
        result = 31 * result + command.hashCode()
        result = 31 * result + parameters.contentHashCode()
        result = 31 * result + returnType.hashCode()
        result = 31 * result + (description?.hashCode() ?: 0)
        result = 31 * result + (returnValuesListIds?.hashCode() ?: 0)
        result = 31 * result + requiresOwnr
        result = 31 * result + variants.hashCode()
        result = 31 * result + rvalue.hashCode()
        result = 31 * result + lvalue.hashCode()
        result = 31 * result + (lvalueName?.hashCode() ?: 0)
        result = 31 * result + commandGroup.hashCode()
        result = 31 * result + (doifFormat?.hashCode() ?: 0)
        result = 31 * result + requiresCreatureOwnr.hashCode()
        return result
    }
}


private fun formatNameWithType(name: String, type: ValueType): String {
    return name + type.simpleName.let { simpleName ->
        if (simpleName[0] == '[')
            " $simpleName"
        else
            " ($simpleName)"
    }
}

/**
 * Represents a parameter to a CAOS command
 */
@Serializable
internal data class CaosParameter(
    val index: Int,
    val name: String,
    val typeId: Int,
    val valuesListIds: Map<String, Int>? = null,
    val description: String? = null,
    val min: Int? = null,
    val max: Int? = null
) {

    constructor(
        index: Int,
        name: String,
        type: ValueType,
        valuesListIds: Map<String, Int>? = mapOf(),
        description: String? = null,
        min: Int? = null,
        max: Int? = null
    ) : this(
        index = index,
        name = name,
        typeId = type.value,
        valuesListIds = valuesListIds,
        description = description,
        min = min,
        max = max
    )

    val type: ValueType by lazy {
        ValueType.fromIntValue(typeId)
    }

    val valuesList: HasGetter<CaosVariant, CaosValuesList?> by lazy {
        if (valuesListIds.isNullOrEmpty()) {
            HasGetterImpl {
                null
            }
        } else {
            HasGetterImpl get@{ key ->
                val valuesListId = valuesListIds[key.code]
                    ?: return@get null
                CaosLibs.valuesList[valuesListId]
            }
        }
    }

}

internal fun CaosParameter.toICaosParameter(variant: String): ICaosParameter {
    return ICaosParameter(this, variant)
}

/**
 * A list of known values for a parameter or return value
 * Useful in generating suggestions
 */
@Serializable
@JsExport
@JsName("CaosValuesList")
data class CaosValuesList(
    @JsName("id")
    val id: Int,
    @JsName("name")
    val name: String,
    @JsName("values")
    val values: Array<CaosValuesListValue>,
    @JsName("description")
    val description: String? = null,
    @JsName("extensionType")
    val extensionType: String? = null
) {

    private val negative = values.filter { it.not }
    private val greaterThan = values.filter { it.greaterThan }

    /**
     * Gets command checking both literal value and int comparison values
     */
    @JsName("getValueWithString")
    operator fun get(key: String): CaosValuesListValue? {
        key.toIntOrNull()?.let { intValue ->
            return get(intValue)
        }
        return values.firstOrNull { it.value == key }
    }

    /**
     * Gets command using both literal numeric value and value comparison
     */
    @JsName("getValueWithInt")
    operator fun get(key: Int): CaosValuesListValue? {
        return values.firstOrNull { it.intValue == key }
            ?: negative.firstOrNull { it.intValue != key }
            ?: greaterThan.firstOrNull { it.intValue!! < key }
    }

    fun getWithBitFlags(bitFlag: Int): Array<CaosValuesListValue>? {
        if (extensionType notLike "BitFlags")
            return null
        return values.filter filter@{ value ->
            val intValue = value.intValue
                ?: return@filter false
            bitFlag and intValue > 0
        }.toTypedArray()
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is CaosValuesList) return false

        if (id != other.id) return false
        if (name != other.name) return false
        if (!values.contentEquals(other.values)) return false
        if (description != other.description) return false
        if (extensionType != other.extensionType) return false
        if (negative != other.negative) return false
        if (greaterThan != other.greaterThan) return false

        return true
    }

    override fun hashCode(): Int {
        var result = id
        result = 31 * result + name.hashCode()
        result = 31 * result + values.contentHashCode()
        result = 31 * result + (description?.hashCode() ?: 0)
        result = 31 * result + (extensionType?.hashCode() ?: 0)
        result = 31 * result + negative.hashCode()
        result = 31 * result + greaterThan.hashCode()
        return result
    }

    val bitflag: Boolean by lazy {
        extensionType?.equals("BitFlags", true) ?: false
    }
}

/**
 * Represents a value in a values list
 */
@Serializable
@JsExport
@JsName("ValuesListValue")
data class CaosValuesListValue(
    @JsName("value")
    val value: String,
    @JsName("name")
    val name: String,
    @JsName("description")
    val description: String? = null,
    @JsName("beforeRegion")
    val beforeRegion: String? = null
) {
    @JsName("intValue")
    val intValue: Int? by lazy {
        val value = value.trim()
        if (value.startsWith(">") || value.startsWith("!"))
            value.substring(1).toIntOrNull()
        else
            value.toIntOrNull()
    }

    @JsName("negatedValue")
    val not by lazy {
        value.startsWith("!")
    }

    @JsName("greaterThanValue")
    val greaterThan by lazy {
        intValue != null && value.startsWith(">")
    }

}


/**
 * Named game var type enum
 */
@Suppress("SpellCheckingInspection")
enum class CaosScriptNamedGameVarType(val value: Int, val token: String) {
    NAME(1, "NAME"),
    EAME(2, "EAME"),
    GAME(3, "GAME"),
    MAME(4, "MAME");

    companion object {
        fun fromValue(value: Int): CaosScriptNamedGameVarType {
            return when (value) {
                NAME.value -> NAME
                EAME.value -> EAME
                GAME.value -> GAME
                MAME.value -> MAME
                else -> throw Exception("Invalid named game variable type '$value'")
            }
        }
    }
}


@JsExport
@JsName("getCommandsForLib")
fun getCommandsForLib(variant:String) : Commands {
    val lib = CaosLibs[variant]
    return Commands(
        commands = lib.commands.map { it.toJsCommand(variant) }.toTypedArray(),
        lvalues = lib.lvalues.map { it.toJsCommand(variant) }.toTypedArray(),
        rvalues = lib.rvalues.map { it.toJsCommand(variant) }.toTypedArray()
    )
}


@JsExport
@JsName("Commands")
data class Commands(
    @JsName("commands")
    val commands:Array<ICaosCommand>,
    @JsName("rvalues")
    val rvalues:Array<ICaosCommand>,
    @JsName("lvalues")
    val lvalues:Array<ICaosCommand>
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Commands) return false

        if (!commands.contentEquals(other.commands)) return false
        if (!rvalues.contentEquals(other.rvalues)) return false
        if (!lvalues.contentEquals(other.lvalues)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = commands.contentHashCode()
        result = 31 * result + rvalues.contentHashCode()
        result = 31 * result + lvalues.contentHashCode()
        return result
    }
}
