internal object PositionSerializer: KSerializer<Position> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("Position") {
            this.element<Int>("line")
            this.element<Int>("character")
        }
    }

    override fun deserialize(decoder: Decoder): Position {
        val structure = decoder.beginStructure(descriptor)
        var index = structure.decodeElementIndex(descriptor)
        var line: Int? = null
        var character: Int? = null
        while (index != CompositeDecoder.DECODE_DONE) {
            when (index) {
                0 -> line = decoder.decodeInt()
                1 -> character = decoder.decodeInt()
            }
            index = structure.decodeElementIndex(descriptor)
        }
        structure.endStructure(descriptor)
        return PositionImpl(
            line ?: throw SerializationException("Position is missing element: \"line\""),
            character ?: throw SerializationException("Position is missing element: \"character\"")
        )
    }

    override fun serialize(encoder: Encoder, value: Position) {
        val structure = encoder.beginStructure(descriptor)
        structure.encodeIntElement(descriptor, 0, value.line)
        structure.encodeIntElement(descriptor, 1, value.character)
        structure.endStructure(descriptor)
    }
}


internal object RangeSerializer: KSerializer<Range> {

    const val RANGE_WITH_INDEX = "RangeWithIndex"
    const val RANGE_WITHOUT_INDEX = "Range"
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("Range") {
            this.element<String>("type", isOptional = true)
            element("start", PositionSerializer.descriptor, emptyList(), false)
            element("end", PositionSerializer.descriptor, emptyList(), false)
            this.element<Int>("startIndex", isOptional = true)
            this.element<Int>("endIndex", isOptional = true)
            this.element<Int>("parserIndex", isOptional = true)
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    override fun deserialize(decoder: Decoder): Range {
        val structure = decoder.beginStructure(descriptor)
        var index = structure.decodeElementIndex(descriptor)
        var type: String? = null
        var start: Position? = null
        var end: Position? = null
        var startIndex: Int? = null
        var endIndex: Int? = null
        var parserIndex: Int? = null
        while (index != CompositeDecoder.DECODE_DONE) {
            when (index) {
                0 -> type = decoder.decodeString()
                1 -> start = decoder.decodeSerializableValue(PositionSerializer)
                2 -> end =  decoder.decodeSerializableValue(PositionSerializer)
                3 -> startIndex = decoder.decodeInt()
                4 -> endIndex = decoder.decodeInt()
                5 -> parserIndex = decoder.decodeNullableSerializableValue(Int.serializer().nullable)
            }
            index = structure.decodeElementIndex(descriptor)
        }
        structure.endStructure(descriptor)
        return when (type) {
            RANGE_WITH_INDEX -> {
                RangeWithIndexImpl(
                    start = start ?: throw SerializationException("Range with index is missing \"start\""),
                    end = end!!,
                    startIndex = startIndex ?: throw SerializationException("Range with index is missing \"startIndex\""),
                    endIndex = endIndex  ?: throw SerializationException("Range with index is missing \"endIndex\""),
                    parserIndex = parserIndex
                )
            }
            RANGE_WITHOUT_INDEX, null -> {
                RangeImpl(
                    start = start ?: throw SerializationException("Range without index is missing \"start\""),
                    end = end ?: throw SerializationException("Range without index is missing \"end\"")
                )
            }
            else -> {
                throw SerializationException("Invalid range type: $type")
            }
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    override fun serialize(encoder: Encoder, value: Range) {
        val structure = encoder.beginStructure(descriptor)
        if (isRangeWithIndex(value)) {
            val range = value as RangeWithIndex
            structure.encodeStringElement(descriptor, 0, RANGE_WITH_INDEX)
            structure.encodeIntElement(descriptor, 3, range.startIndex)
            structure.encodeIntElement(descriptor, 4, range.endIndex)
            structure.encodeNullableSerializableElement(descriptor, 5, Int.serializer(), range.parserIndex)
        } else {
            structure.encodeStringElement(descriptor, 0, RANGE_WITHOUT_INDEX)
        }
        structure.encodeSerializableElement(descriptor, 1, PositionSerializer, value.start)
        structure.encodeSerializableElement(descriptor, 2, PositionSerializer, value.end)
        structure.endStructure(descriptor)
    }
}




internal object RangeWithIndexSerializer: KSerializer<RangeWithIndex> {
    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("IRangeWithIndex") {
            this.element<String>("type")
            element("start", PositionSerializer.descriptor, emptyList(), false)
            element("end", PositionSerializer.descriptor, emptyList(), false)
            this.element<Int>("startIndex", isOptional = true)
            this.element<Int>("endIndex", isOptional = true)
            this.element<Int>("parserIndex", isOptional = true)
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    override fun deserialize(decoder: Decoder): RangeWithIndex {
        val structure = decoder.beginStructure(descriptor)
        var index = structure.decodeElementIndex(descriptor)
        var type: String? = null
        var start: Position? = null
        var end: Position? = null
        var startIndex: Int? = null
        var endIndex: Int? = null
        var parserIndex: Int? = null
        while (index != CompositeDecoder.DECODE_DONE) {
            when (index) {
                0 -> type = decoder.decodeNullableSerializableValue(String.serializer().nullable)
                1 -> start = decoder.decodeSerializableValue(PositionSerializer)
                2 -> end =  decoder.decodeSerializableValue(PositionSerializer)
                3 -> startIndex = decoder.decodeInt()
                4 -> endIndex = decoder.decodeInt()
                5 -> parserIndex = decoder.decodeNullableSerializableValue(Int.serializer().nullable)
            }
            index = structure.decodeElementIndex(descriptor)
        }
        structure.endStructure(descriptor)
        return if (type == RangeSerializer.RANGE_WITH_INDEX || type == null) {
            RangeWithIndexImpl(
                start = start!!,
                end = end!!,
                startIndex = startIndex!!,
                endIndex = endIndex!!,
                parserIndex = parserIndex
            )
        } else {
            throw SerializationException("Invalid range type: $type")
        }
    }

    @OptIn(ExperimentalSerializationApi::class)
    override fun serialize(encoder: Encoder, value: RangeWithIndex) {
        val structure = encoder.beginStructure(descriptor)
        structure.encodeStringElement(descriptor, 0, RangeSerializer.RANGE_WITH_INDEX)
        structure.encodeSerializableElement(descriptor, 1, PositionSerializer, value.start)
        structure.encodeSerializableElement(descriptor, 2, PositionSerializer, value.end)
        structure.encodeIntElement(descriptor, 3, value.startIndex)
        structure.encodeIntElement(descriptor, 4, value.endIndex)
        structure.encodeNullableSerializableElement(descriptor, 5, Int.serializer(), value.parserIndex)
        structure.endStructure(descriptor)
    }
}
internal expect fun isRangeWithIndex(range: Range): Boolean

internal object TextEditSerializer: KSerializer<TextEdit> {
    private const val RANGE_INDEX = 0
    private const val TEXT_INDEX = 1

    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("TextEdit") {
            element("range", RangeSerializer.descriptor)
            element<String>("new_text")
        }
    }

    override fun deserialize(decoder: Decoder): TextEdit {
        val descriptor = descriptor
        var range: Range? = null
        var newText: String? = null
        val ob = decoder.beginStructure(descriptor)
        var index: Int
        while (ob.decodeElementIndex(descriptor).also { index = it } != CompositeDecoder.DECODE_DONE) {
            when (index) {
                RANGE_INDEX -> range = ob.decodeSerializableElement(descriptor, index, RangeSerializer)
                TEXT_INDEX -> newText = ob.decodeStringElement(descriptor, index)
            }
        }
        ob.endStructure(descriptor)
        if (range == null || newText == null) {
            val error = if (range == null && newText == null) {
                "Invalid EditText serialized data. Missing: \"range\" and \"new_text\" values"
            } else if (range == null) {
                "Invalid EditText serialized data. Missing: \"range\" value"
            } else {
                "Invalid EditText serialized data. Missing: \"new_text\" value"
            }
            throw SerializationException(error)
        }
        return TextEditImpl(
            range = range,
            newText = newText
        )
    }

    override fun serialize(encoder: Encoder, value: TextEdit) {
        val descriptor = descriptor
        val ob = encoder.beginStructure(descriptor)
        ob.encodeSerializableElement(descriptor, RANGE_INDEX, RangeSerializer, value.range)
        ob.encodeStringElement(descriptor, TEXT_INDEX, value.newText)
        ob.endStructure(descriptor)
    }

}


internal object InlayHintSerializer: KSerializer<InlayHint> {

    // Serializers
    private val textEditListSerializer = ListSerializer(TextEditSerializer).nullable

    // Indices
    private const val POSITION_INDEX = 0 // position: Position
    private const val LABEL_INDEX = 1 // label: String
    private const val KIND_INDEX = 2 //kind: Int?
    private const val TEXT_EDITS_ARRAY_INDEX = 3// textEdits: Array<TextEdit>
    private const val TOOLTIP_INDEX = 4 //tooltip: String?
    private const val PADDING_LEFT_INDEX = 5 //paddingLeft: Boolean?
    private const val PADDING_RIGHT_INDEX = 6 //paddingRight: Boolean?

    override val descriptor: SerialDescriptor by lazy {
        buildClassSerialDescriptor("InlayHint") {
            element("position", PositionSerializer.descriptor)
            element<String>("label")
            element<Int?>("kind")
            element<Array<TextEdit>>("text_edits")
            element<String?>("tooltip")
            element<Boolean>("padding_left")
            element<Boolean>("padding_right")
//            element<Any>("")
        }
    }

    override fun deserialize(decoder: Decoder): InlayHint {
        val descriptor = descriptor
        val ob = decoder.beginStructure(descriptor)
        var index: Int
        var position: Position? = null
        var label: String? = null
        var kind: Int? = null
        var edits: Array<TextEdit>? = null
        var tooltip: String? = null
        var paddingLeft: Boolean? = null
        var paddingRight: Boolean? = null
        while (ob.decodeElementIndex(descriptor).also { index = it} != CompositeDecoder.DECODE_DONE) {
            when (index) {
                POSITION_INDEX -> position = ob.decodeSerializableElement(
                    descriptor,
                    index,
                    PositionImpl.serializer()
                )
                LABEL_INDEX -> label = ob.decodeStringElement(
                    descriptor,
                    index
                )
                KIND_INDEX -> kind = ob.decodeNullableIntElement(
                    descriptor,
                    index
                )
                TEXT_EDITS_ARRAY_INDEX -> edits = ob.decodeSerializableElement(
                    descriptor,
                    index,
                    textEditListSerializer,
                )?.toTypedArray()
                TOOLTIP_INDEX -> tooltip = ob.decodeNullableStringElement(
                    descriptor,
                    index
                )
                PADDING_LEFT_INDEX -> paddingLeft = ob.decodeNullableBooleanElement(
                    descriptor,
                    index
                )
                PADDING_RIGHT_INDEX -> paddingRight = ob.decodeNullableBooleanElement(
                    descriptor,
                    index
                )
            }
        }
        ob.endStructure(descriptor)
        if (position == null || label == null) {
            val missing = if (position == null && label == null) {
                "position, label"
            } else if (position == null) {
                "position"
            } else {
                "label"
            }
            throw SerializationException("InlayHint is missing element: [$missing]")
        }
        return InlayHintImpl(
            position = position,
            label = label,
            kind = kind,
            textEdits = edits,
            tooltip = tooltip,
            paddingLeft = paddingLeft,
            paddingRight = paddingRight
        )
    }

    override fun serialize(encoder: Encoder, value: InlayHint) {
        val ob = encoder.beginStructure(descriptor)
        ob.encodeSerializableElement(descriptor, POSITION_INDEX, PositionSerializer, value.position)
        ob.encodeStringElement(descriptor, LABEL_INDEX, value.label)
        ob.encodeNullableIntElement(descriptor, KIND_INDEX, value.kind)
        ob.encodeSerializableElement(
            descriptor,
            TEXT_EDITS_ARRAY_INDEX,
            textEditListSerializer,
            value.textEdits?.toList()
        )
        ob.encodeNullableStringElement(descriptor, TOOLTIP_INDEX, value.tooltip)
        ob.encodeNullableBooleanElement(descriptor, PADDING_LEFT_INDEX, value.paddingLeft)
        ob.encodeNullableBooleanElement(descriptor, PADDING_RIGHT_INDEX, value.paddingRight)
        ob.endStructure(descriptor)
    }

}